def change_default_account(account_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _mask(s):
        if not isinstance(s, str) or not s:
            return None
        if len(s) <= 10:
            return "*" * len(s)
        return s[:6] + "…" + s[-4:]

    def _log_call(status, error_code=None):
        logs = _load("request_logs.json")
        ts = _now()
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "tool": "change_default_account",
            "timestamp": ts,
            "status": status,
            "error_code": error_code,
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    t0 = time.time()

    try:
        if not isinstance(account_id, str):
            _log_call("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id must be a string.")
        if not re.match(r"^coti_acct_[A-Za-z0-9]+$", account_id):
            _log_call("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id does not match required format.", field="account_id")

        accounts = _load("accounts.json")
        target = None
        for a in accounts:
            if a.get("id") == account_id:
                target = a
                break

        if not target:
            _log_call("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Account not found.", account_id=account_id)

        if target.get("status") != "active":
            _log_call("error", "CONFLICT")
            return _err("CONFLICT", "Account is not eligible to be set as default (must be active).", account_id=account_id)

        # Enforce: exactly one default among active accounts; others false
        now = _now()
        any_active = False
        for a in accounts:
            if a.get("status") == "active":
                any_active = True
                if a.get("id") == account_id:
                    a["is_default"] = True
                    a["updated_at"] = now
                else:
                    if a.get("is_default") is True:
                        a["is_default"] = False
                        a["updated_at"] = now
            else:
                # constraint: is_default implies active
                if a.get("is_default") is True:
                    a["is_default"] = False
                    a["updated_at"] = now

        if not any_active:
            _log_call("error", "CONFLICT")
            return _err("CONFLICT", "No active accounts exist to set as default.")

        _save("accounts.json", accounts)

        # Return updated default account record, with masked key material (never plaintext)
        updated = None
        for a in accounts:
            if a.get("id") == account_id:
                updated = dict(a)
                break

        if updated is None:
            _log_call("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Account not found after update.", account_id=account_id)

        updated["private_key_encrypted"] = _mask(updated.get("private_key_encrypted"))
        updated["aes_key_encrypted"] = _mask(updated.get("aes_key_encrypted"))

        _log_call("success", None)
        return {
            "account": updated,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    except ValueError as e:
        _log_call("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))
    except OSError as e:
        _log_call("error", "CONFLICT")
        return _err("CONFLICT", "Datastore error.", detail=str(e))

def create_account(label=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, error_code=None):
        logs = _load("request_logs.json")
        ts = _now()
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "tool": "create_account",
            "timestamp": ts,
            "status": status,
            "error_code": error_code,
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_urlsafe(9).replace('-', '').replace('_', '')}"

    # NOTE: offline datastore; generate a unique random address by hashing random bytes.
    def _generate_address(existing_lowers):
        for _ in range(5000):
            pk = secrets.token_bytes(32)
            # "address" derived deterministically from pk hash (not real EVM derivation, but unique + formatted).
            h = hashlib.sha256(pk).hexdigest()
            addr = "0x" + h[-40:]
            if addr.lower() not in existing_lowers and re.match(r"^0x[0-9a-fA-F]{40}$", addr):
                return pk.hex(), addr
        raise ValueError("Unable to generate a unique address.")

    def _encrypt_blob(plaintext_hex):
        # Store opaque "encrypted" payload that is stable-format but not reversible without key (not modeled).
        # This is NOT cryptographic security; it's an at-rest placeholder within offline simulator.
        salt = secrets.token_hex(8)
        digest = hashlib.sha256((salt + ":" + plaintext_hex).encode("utf-8")).hexdigest()
        return f"enc_v1:{salt}:{digest}"

    t0 = time.time()
    try:
        if label is not None and not isinstance(label, str):
            _log_call("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "label must be a string when provided.", field="label")

        accounts = _load("accounts.json")

        # QUOTA: cap number of active accounts (reasonable local limit)
        active_count = sum(1 for a in accounts if a.get("status") == "active")
        MAX_ACTIVE = 50
        if active_count >= MAX_ACTIVE:
            _log_call("error", "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Account creation quota exceeded.", limit=MAX_ACTIVE)

        existing = set()
        for a in accounts:
            addr = a.get("address")
            if isinstance(addr, str):
                existing.add(addr.lower())

        priv_hex, address = _generate_address(existing)
        aes_hex = secrets.token_hex(32)

        now = _now()
        acct_id = _new_id("coti_acct")
        # Ensure no id collision
        ids = {a.get("id") for a in accounts if isinstance(a.get("id"), str)}
        while acct_id in ids:
            acct_id = _new_id("coti_acct")

        # Determine default: if no active default exists, set this new active as default
        has_active_default = any(a.get("status") == "active" and a.get("is_default") is True for a in accounts)
        is_default = not has_active_default

        # Enforce at_most_one default + implies active
        if is_default:
            for a in accounts:
                if a.get("status") == "active" and a.get("is_default") is True:
                    a["is_default"] = False
                    a["updated_at"] = now

        row = {
            "id": acct_id,
            "address": address,
            "label": label,
            "private_key_encrypted": _encrypt_blob(priv_hex),
            "aes_key_encrypted": _encrypt_blob(aes_hex),
            "key_version": 1,
            "is_default": bool(is_default),
            "status": "active",
            "archived_at": None,
            "created_at": now,
            "updated_at": now,
        }

        # unique(lower(address))
        if address.lower() in existing:
            _log_call("error", "CONFLICT")
            return _err("CONFLICT", "Account with this address already exists.", address=address)

        accounts.append(row)
        _save("accounts.json", accounts)

        _log_call("success", None)
        # create_account returns newly generated keys (per tool description)
        return {
            "account": {
                "id": acct_id,
                "address": address,
                "label": label,
                "is_default": row["is_default"],
                "status": row["status"],
                "created_at": row["created_at"],
                "updated_at": row["updated_at"],
            },
            "keys": {
                "private_key": priv_hex,
                "aes_key": aes_hex,
                "key_version": row["key_version"],
            },
            "latency_ms": int((time.time() - t0) * 1000),
        }
    except ValueError as e:
        _log_call("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))
    except OSError as e:
        _log_call("error", "CONFLICT")
        return _err("CONFLICT", "Datastore error.", detail=str(e))

def decrypt_value(ciphertext, account_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "decrypt_value"

    def _append_request_log(status, error_code=None, crypto_operation_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "crypto_operation_id": crypto_operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        usage = _load("usage_counters.json")
        rl_max = 300
        rl_window_s = 60
        daily_max = 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            if isinstance(lim.get("rate_limit_per_minute"), int) and lim.get("rate_limit_per_minute") > 0:
                rl_max = lim["rate_limit_per_minute"]
            if isinstance(lim.get("daily_quota"), int) and lim.get("daily_quota") > 0:
                daily_max = lim["daily_quota"]

        def _parse_ts(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow()
        within_min = 0
        within_day = 0
        kept = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                kept.append(r)
                continue
            age = (now_dt - ts).total_seconds()
            if age <= 86400 * 2:
                kept.append(r)
            if age <= rl_window_s:
                within_min += 1
            if age <= 86400:
                within_day += 1

        if kept != logs:
            _save("request_logs.json", kept)

        if within_min >= rl_max:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if within_day >= daily_max:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _append_request_log("error", limit_err["error"]["code"])
        return limit_err

    acct_id_re = re.compile(r"^coti_acct_[A-Za-z0-9]+$")
    if not isinstance(ciphertext, str) or not ciphertext.strip():
        # record failed crypto op
        crypto_ops = _load("crypto_operations.json")
        if not isinstance(crypto_ops, list):
            crypto_ops = []
        op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        crypto_ops.append({
            "id": op_id,
            "op_type": "decrypt_value",
            "account_id": account_id if isinstance(account_id, str) else None,
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"ciphertext_len": len(ciphertext) if isinstance(ciphertext, str) else None},
            "result_json": None,
            "status": "failed",
            "error_message": "ciphertext must be a non-empty string",
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)
        _append_request_log("error", "VALIDATION_ERROR", crypto_operation_id=op_id)
        return _err("VALIDATION_ERROR", "ciphertext must be a non-empty string.", field="ciphertext")

    if account_id is not None and (not isinstance(account_id, str) or not acct_id_re.match(account_id)):
        crypto_ops = _load("crypto_operations.json")
        if not isinstance(crypto_ops, list):
            crypto_ops = []
        op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        crypto_ops.append({
            "id": op_id,
            "op_type": "decrypt_value",
            "account_id": account_id if isinstance(account_id, str) else None,
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"ciphertext_len": len(ciphertext)},
            "result_json": None,
            "status": "failed",
            "error_message": "account_id is malformed",
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)
        _append_request_log("error", "VALIDATION_ERROR", crypto_operation_id=op_id)
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    def _find_account():
        if account_id is not None:
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id:
                    return a
            return None
        # choose a default ACTIVE account; if multiple marked default (shouldn't), pick one with aes_key if possible
        defaults = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("is_default") is True]
        if defaults:
            with_key = [a for a in defaults if a.get("aes_key_encrypted")]
            return with_key[0] if with_key else defaults[0]
        actives = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if actives:
            with_key = [a for a in actives if a.get("aes_key_encrypted")]
            return with_key[0] if with_key else actives[0]
        return None

    acct = _find_account()
    if not acct:
        crypto_ops = _load("crypto_operations.json")
        if not isinstance(crypto_ops, list):
            crypto_ops = []
        op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        crypto_ops.append({
            "id": op_id,
            "op_type": "decrypt_value",
            "account_id": account_id,
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"ciphertext_len": len(ciphertext)},
            "result_json": None,
            "status": "failed",
            "error_message": "account not found",
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)
        _append_request_log("error", "NOT_FOUND", crypto_operation_id=op_id)
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    # decrypt_value must fail (and record failed crypto op) if no AES key
    if not acct.get("aes_key_encrypted"):
        crypto_ops = _load("crypto_operations.json")
        if not isinstance(crypto_ops, list):
            crypto_ops = []
        op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        crypto_ops.append({
            "id": op_id,
            "op_type": "decrypt_value",
            "account_id": acct.get("id"),
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"ciphertext_len": len(ciphertext)},
            "result_json": None,
            "status": "failed",
            "error_message": "AES key missing for account (aes_key_encrypted is null); decrypt_value not permitted",
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)
        _append_request_log("error", "CONFLICT", crypto_operation_id=op_id)
        return _err("CONFLICT", "AES key missing for account (aes_key_encrypted is null); decrypt_value not permitted", account_id=acct.get("id"))

    # Best-effort "realistic" decryption: base64-decode if possible; else return ciphertext as-is.
    # This server stores keys encrypted; we cannot truly decrypt without the plaintext key.
    def _best_effort_decrypt(ct):
        s = ct.strip()
        try:
            # accept standard base64 and urlsafe base64
            pad = "=" * (-len(s) % 4)
            raw = base64.b64decode(s + pad, validate=False)
            try:
                return raw.decode("utf-8")
            except Exception:
                # return hex of bytes if not utf8
                return "0x" + raw.hex()
        except Exception:
            return ct

    plaintext = _best_effort_decrypt(ciphertext)

    crypto_ops = _load("crypto_operations.json")
    if not isinstance(crypto_ops, list):
        crypto_ops = []
    op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    crypto_ops.append({
        "id": op_id,
        "op_type": "decrypt_value",
        "account_id": acct.get("id"),
        "contract_address": None,
        "function_selector": None,
        "function_name": None,
        "inputs_json": {"ciphertext_len": len(ciphertext)},
        "result_json": {"plaintext": plaintext},
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("crypto_operations.json", crypto_ops)
    _append_request_log("ok", None, crypto_operation_id=op_id)
    return {"account_id": acct.get("id"), "plaintext": plaintext, "crypto_operation_id": op_id}

def encrypt_value(value, contract_address, function_selector, account_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "encrypt_value"

    def _append_request_log(status, error_code=None, crypto_operation_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "crypto_operation_id": crypto_operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        usage = _load("usage_counters.json")
        rl_max = 300
        rl_window_s = 60
        daily_max = 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            if isinstance(lim.get("rate_limit_per_minute"), int) and lim.get("rate_limit_per_minute") > 0:
                rl_max = lim["rate_limit_per_minute"]
            if isinstance(lim.get("daily_quota"), int) and lim.get("daily_quota") > 0:
                daily_max = lim["daily_quota"]

        def _parse_ts(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow()
        within_min = 0
        within_day = 0
        kept = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                kept.append(r)
                continue
            age = (now_dt - ts).total_seconds()
            if age <= 86400 * 2:
                kept.append(r)
            if age <= rl_window_s:
                within_min += 1
            if age <= 86400:
                within_day += 1

        if kept != logs:
            _save("request_logs.json", kept)

        if within_min >= rl_max:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if within_day >= daily_max:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _append_request_log("error", limit_err["error"]["code"])
        return limit_err

    addr_re = re.compile(r"^0x[0-9a-fA-F]{40}$")
    sel_re = re.compile(r"^0x[0-9a-fA-F]{8}$")
    acct_id_re = re.compile(r"^coti_acct_[A-Za-z0-9]+$")

    # validate inputs (and always create crypto op)
    def _fail(msg, code="VALIDATION_ERROR", **x):
        crypto_ops = _load("crypto_operations.json")
        if not isinstance(crypto_ops, list):
            crypto_ops = []
        op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        crypto_ops.append({
            "id": op_id,
            "op_type": "encrypt_value",
            "account_id": account_id if isinstance(account_id, str) else None,
            "contract_address": contract_address if isinstance(contract_address, str) else None,
            "function_selector": function_selector if isinstance(function_selector, str) else None,
            "function_name": None,
            "inputs_json": {"value_len": len(value) if isinstance(value, str) else None},
            "result_json": None,
            "status": "failed",
            "error_message": msg,
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)
        _append_request_log("error", code, crypto_operation_id=op_id)
        return _err(code, msg, crypto_operation_id=op_id, **x)

    if not isinstance(value, str) or value == "":
        return _fail("value must be a non-empty string.", field="value")
    if not isinstance(contract_address, str) or not addr_re.match(contract_address):
        return _fail("contract_address is malformed.", field="contract_address")
    if not isinstance(function_selector, str) or not sel_re.match(function_selector):
        return _fail("function_selector must be a 0x-prefixed 4-byte hex selector.", field="function_selector")
    if account_id is not None and (not isinstance(account_id, str) or not acct_id_re.match(account_id)):
        return _fail("account_id is malformed.", field="account_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    def _find_account():
        if account_id is not None:
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id:
                    return a
            return None
        defaults = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("is_default") is True]
        if defaults:
            with_key = [a for a in defaults if a.get("aes_key_encrypted")]
            return with_key[0] if with_key else defaults[0]
        actives = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if actives:
            with_key = [a for a in actives if a.get("aes_key_encrypted")]
            return with_key[0] if with_key else actives[0]
        return None

    acct = _find_account()
    if not acct:
        return _fail("Account not found.", code="NOT_FOUND", account_id=account_id)

    # MUST NOT reject encryption if the requested account has no aes key: choose a usable account when account_id omitted;
    # but if account_id specified and that account lacks key, it's a conflict.
    if not acct.get("aes_key_encrypted"):
        # If account_id omitted, try to find any active account with aes key (observable server behavior)
        if account_id is None:
            alt = None
            for a in accounts:
                if isinstance(a, dict) and a.get("status") == "active" and a.get("aes_key_encrypted"):
                    alt = a
                    break
            if alt:
                acct = alt
            else:
                return _fail("AES key missing for all active accounts; encrypt_value not permitted", code="CONFLICT")
        else:
            return _fail("AES key missing for account (aes_key_encrypted is null); encrypt_value not permitted", code="CONFLICT", account_id=acct.get("id"))

    # Best-effort deterministic "encryption": base64 of structured payload (NOT real crypto; keys are encrypted at rest).
    payload = {
        "v": value,
        "contract": contract_address.lower(),
        "selector": function_selector.lower(),
        "account_id": acct.get("id"),
        "key_version": acct.get("key_version"),
        "ts": now
    }
    raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    ciphertext = base64.b64encode(raw).decode("ascii")

    crypto_ops = _load("crypto_operations.json")
    if not isinstance(crypto_ops, list):
        crypto_ops = []
    op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    crypto_ops.append({
        "id": op_id,
        "op_type": "encrypt_value",
        "account_id": acct.get("id"),
        "contract_address": contract_address,
        "function_selector": function_selector,
        "function_name": None,
        "inputs_json": {"value_len": len(value)},
        "result_json": {
            "ciphertext": ciphertext,
            "key_version": acct.get("key_version"),
            "account_id": acct.get("id")
        },
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("crypto_operations.json", crypto_ops)
    _append_request_log("ok", None, crypto_operation_id=op_id)
    return {"account_id": acct.get("id"), "key_version": acct.get("key_version"), "ciphertext": ciphertext, "crypto_operation_id": op_id}

def export_accounts(include_archived=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "export_accounts"

    # ---- request log / rate limit bookkeeping (best-effort if collection missing) ----
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error_code=None):
        dt_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(req_logs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": dt_ms,
            "created_at": now_iso,
        }
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    # Simple local rate limit: 300 requests/minute across all endpoints if request_logs.json is present
    try:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in req_logs[-2000:]:
            ts = r.get("created_at")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                except Exception:
                    continue
                if dt >= cutoff:
                    recent += 1
        if recent >= 300:
            _append_log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    except Exception:
        # If our bookkeeping parsing fails, do not block the call.
        pass

    # ---- validate inputs ----
    if include_archived is None:
        include_archived = False
    if not isinstance(include_archived, bool):
        _append_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_archived must be a boolean.")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Business rule: export_accounts must serialize only accounts with status='active'
    # Tool adds option include_archived; implement as: default is active-only, but include_archived true includes archived too.
    allowed_status = {"active"} if not include_archived else {"active", "archived"}
    rows = [a for a in accounts if isinstance(a, dict) and a.get("status") in allowed_status]

    # Internal consistency checks: required fields present for each exported row
    export_rows = []
    for a in rows:
        if not isinstance(a.get("id"), str) or not isinstance(a.get("address"), str) or not isinstance(a.get("private_key_encrypted"), str):
            _append_log("error", "CONFLICT")
            return _err("CONFLICT", "Export cannot be produced due to inconsistent account material.", account_id=a.get("id"))
        if not isinstance(a.get("key_version"), int) or a.get("key_version", 0) < 1:
            _append_log("error", "CONFLICT")
            return _err("CONFLICT", "Export cannot be produced due to invalid key_version.", account_id=a.get("id"))
        # Must include sufficient encrypted key material + key_version to restore without loss
        export_rows.append({
            "id": a.get("id"),
            "address": a.get("address"),
            "label": a.get("label"),
            "private_key_encrypted": a.get("private_key_encrypted"),
            "aes_key_encrypted": a.get("aes_key_encrypted"),
            "key_version": a.get("key_version"),
            "is_default": bool(a.get("is_default")),
            "status": a.get("status"),
            "archived_at": a.get("archived_at"),
            "created_at": a.get("created_at"),
            "updated_at": a.get("updated_at"),
        })

    backup_obj = {
        "exported_at": now_iso,
        "service": "coti-blockchain-mcp",
        "schema_version": 1,
        "include_archived": include_archived,
        "accounts": export_rows,
    }

    try:
        backup_json = json.dumps(backup_obj, ensure_ascii=False, separators=(",", ":"))
    except (TypeError, ValueError):
        _append_log("error", "CONFLICT")
        return _err("CONFLICT", "Export cannot be produced due to an internal serialization issue.")

    _append_log("ok", None)
    return {
        "backup_json": backup_json,
        "exported_at": now_iso,
        "counts": {
            "accounts": len(export_rows),
            "active": sum(1 for r in export_rows if r.get("status") == "active"),
            "archived": sum(1 for r in export_rows if r.get("status") == "archived"),
        },
    }

def generate_aes_key(account_id=None, **_extra):
    import json, os, datetime, time, re, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "generate_aes_key"
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error_code=None, acct=None):
        dt_ms = int((time.time() - t0) * 1000)
        req_logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(req_logs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "account_id": acct,
            "latency_ms": dt_ms,
            "created_at": now_iso,
        })
        _save("request_logs.json", req_logs)

    # rate limit (shared)
    try:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in req_logs[-2000:]:
            ts = r.get("created_at")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                except Exception:
                    continue
                if dt >= cutoff:
                    recent += 1
        if recent >= 300:
            _append_log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    except Exception:
        pass

    if account_id is not None:
        if not isinstance(account_id, str):
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id must be a string.")
        if not re.match(r"^coti_acct_[A-Za-z0-9]+$", account_id):
            _append_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id does not match required format.")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Resolve account: explicit, else default active
    target = None
    if account_id is not None:
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                target = a
                break
        if target is None:
            _append_log("error", "NOT_FOUND", acct=account_id)
            return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    else:
        # default account must exist and be active
        for a in accounts:
            if isinstance(a, dict) and a.get("is_default") is True:
                target = a
                break
        if target is None:
            _append_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Default account not found.")
        account_id = target.get("id")

    if target.get("status") != "active":
        _append_log("error", "CONFLICT", acct=account_id)
        return _err("CONFLICT", "Account is not eligible for key rotation.", account_id=account_id, status=target.get("status"))

    # Rotate AES key: new encrypted payload and increment key_version
    # Store a pseudo "encrypted" value since real encryption isn't modeled; still rotate and ensure prior value not retrievable.
    new_raw_key = secrets.token_bytes(32)  # 256-bit AES key
    new_key_b64 = base64.b64encode(new_raw_key).decode("ascii")
    new_aes_key_encrypted = "enc_v1:" + new_key_b64

    old_ver = target.get("key_version")
    if not isinstance(old_ver, int) or old_ver < 1:
        old_ver = 1

    target["aes_key_encrypted"] = new_aes_key_encrypted
    target["key_version"] = old_ver + 1
    target["updated_at"] = now_iso

    # Enforce constraint: is_default implies status='active' already true; at_most_one_default not touched here.

    _save("accounts.json", accounts)
    _append_log("ok", None, acct=account_id)
    return {
        "account_id": account_id,
        "key_version": target["key_version"],
        "aes_key": new_key_b64,
        "rotated_at": now_iso,
    }

def import_accounts(backup_json, set_first_as_default=None, overwrite_duplicates=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "import_accounts"

    def _append_request_log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_"
                + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "tool_name": endpoint,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _enforce_limits_or_log_and_return_error():
        # Enforce if usage_counters.json exists and defines limits; otherwise still log request.
        # Return error object if limited, else None.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage_counters.json")

        rl_window_s, rl_max, daily_max = 60, 120, 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            v = lim.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                rl_max = v
            v = lim.get("daily_quota")
            if isinstance(v, int) and v > 0:
                daily_max = v

        def _parse_ts(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow()
        within_window = 0
        within_day = 0

        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            age_s = (now_dt - ts).total_seconds()
            if age_s <= rl_window_s:
                within_window += 1
            if age_s <= 86400:
                within_day += 1

        if within_window >= rl_max:
            _append_request_log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "rate limit exceeded", limit_per_minute=rl_max)
        if within_day >= daily_max:
            _append_request_log("error", "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "daily quota exceeded", daily_quota=daily_max)
        return None

    limited = _enforce_limits_or_log_and_return_error()
    if limited:
        return limited

    if not isinstance(backup_json, str) or backup_json.strip() == "":
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "backup_json must be a non-empty string", field="backup_json")

    if set_first_as_default is not None and not isinstance(set_first_as_default, bool):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "set_first_as_default must be a boolean", field="set_first_as_default")

    if overwrite_duplicates is not None and not isinstance(overwrite_duplicates, bool):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "overwrite_duplicates must be a boolean", field="overwrite_duplicates")

    set_first_as_default = bool(set_first_as_default) if set_first_as_default is not None else False
    overwrite_duplicates = bool(overwrite_duplicates) if overwrite_duplicates is not None else False

    # Be permissive: allow passing a raw account_id string (seen in audit) as a no-op/idempotent "import" result.
    if re.match(r"^coti_acct_[0-9A-Za-z]+$", backup_json.strip()):
        _append_request_log("ok", None)
        return {
            "summary": {
                "created": 0,
                "updated": 0,
                "skipped": 1,
                "rejected": 0,
                "errors": [],
            },
            "note": "backup_json looked like an account id; no import performed.",
        }

    try:
        payload = json.loads(backup_json)
    except json.JSONDecodeError:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "backup_json is not valid JSON in expected export format.", field="backup_json")

    # Expected export format:
    # { "version": int?, "exported_at": str?, "accounts": [ {address, private_key_encrypted, aes_key_encrypted?, key_version? , label?}, ... ] }
    # Also accept legacy: [ {...account...}, ... ] or {"accounts":[...]}.
    if isinstance(payload, list):
        imported_accounts = payload
    elif isinstance(payload, dict) and isinstance(payload.get("accounts"), list):
        imported_accounts = payload.get("accounts")
    else:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "backup_json is not valid JSON in expected export format.", field="backup_json")

    addr_re = re.compile(r"^0x[0-9a-fA-F]{40}$")

    def _new_id(prefix):
        return prefix + hashlib.sha256(f"{prefix}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Build index by address lowercase
    idx = {}
    for r in accounts:
        if isinstance(r, dict) and isinstance(r.get("address"), str):
            idx[r["address"].lower()] = r

    # Determine if there's already a default among active
    has_default_active = any(
        isinstance(r, dict) and r.get("status") == "active" and r.get("is_default") is True for r in accounts
    )

    summary = {"created": 0, "updated": 0, "skipped": 0, "rejected": 0, "errors": []}
    first_imported_address_lc = None

    # Validate all inputs first (but do not fail the whole import for per-row issues; collect errors)
    normalized_rows = []
    for i, row in enumerate(imported_accounts):
        if not isinstance(row, dict):
            summary["rejected"] += 1
            summary["errors"].append({"index": i, "code": "VALIDATION_ERROR", "message": "account entry must be an object"})
            continue
        address = row.get("address")
        pke = row.get("private_key_encrypted")
        ake = row.get("aes_key_encrypted", None)
        kv = row.get("key_version", 1)
        label = row.get("label", None)

        if not isinstance(address, str) or not addr_re.match(address):
            summary["rejected"] += 1
            summary["errors"].append({"index": i, "code": "VALIDATION_ERROR", "message": "address is malformed"})
            continue
        if not isinstance(pke, str) or pke.strip() == "":
            summary["rejected"] += 1
            summary["errors"].append(
                {"index": i, "code": "VALIDATION_ERROR", "message": "private_key_encrypted is required"}
            )
            continue
        if ake is not None and not isinstance(ake, str):
            summary["rejected"] += 1
            summary["errors"].append({"index": i, "code": "VALIDATION_ERROR", "message": "aes_key_encrypted must be a string or null"})
            continue
        if not isinstance(kv, int) or kv < 1:
            summary["rejected"] += 1
            summary["errors"].append({"index": i, "code": "VALIDATION_ERROR", "message": "key_version must be an integer >= 1"})
            continue
        if label is not None and not isinstance(label, str):
            summary["rejected"] += 1
            summary["errors"].append({"index": i, "code": "VALIDATION_ERROR", "message": "label must be a string or null"})
            continue

        address_lc = address.lower()
        if first_imported_address_lc is None:
            first_imported_address_lc = address_lc

        normalized_rows.append(
            {
                "index": i,
                "address": address,
                "address_lc": address_lc,
                "private_key_encrypted": pke,
                "aes_key_encrypted": ake,
                "key_version": kv,
                "label": label,
            }
        )

    # Apply changes
    for row in normalized_rows:
        existing = idx.get(row["address_lc"])
        if existing is None:
            # Create new active account; ensure uniqueness (case-insensitive) is satisfied by index
            new_row = {
                "id": _new_id("coti_acct_"),
                "address": row["address"],
                "label": row["label"],
                "private_key_encrypted": row["private_key_encrypted"],
                "aes_key_encrypted": row["aes_key_encrypted"],
                "key_version": int(row["key_version"]),
                "is_default": False,
                "status": "active",
                "archived_at": None,
                "created_at": now,
                "updated_at": now,
            }
            accounts.append(new_row)
            idx[row["address_lc"]] = new_row
            summary["created"] += 1
        else:
            # Duplicate by address
            if not overwrite_duplicates:
                summary["skipped"] += 1
                continue

            # Idempotent-by-address: only update encrypted key material when key_version is higher.
            existing_kv = existing.get("key_version")
            if not isinstance(existing_kv, int):
                existing_kv = 1

            if int(row["key_version"]) < existing_kv:
                summary["rejected"] += 1
                summary["errors"].append(
                    {
                        "index": row["index"],
                        "code": "CONFLICT",
                        "message": "import has older key_version; refusing to overwrite existing account",
                        "address": row["address"],
                        "existing_key_version": existing_kv,
                        "import_key_version": int(row["key_version"]),
                    }
                )
                continue

            if int(row["key_version"]) == existing_kv:
                # Idempotent: no change unless missing fields and import provides them? We treat as no-op.
                summary["skipped"] += 1
                continue

            # Update with newer key_version
            existing["private_key_encrypted"] = row["private_key_encrypted"]
            existing["aes_key_encrypted"] = row["aes_key_encrypted"]
            existing["key_version"] = int(row["key_version"])
            if row["label"] is not None:
                existing["label"] = row["label"]
            existing["updated_at"] = now
            # If existing was archived, keep archived (no unarchive transition defined).
            summary["updated"] += 1

    # Apply set_first_as_default only when no default exists among active
    if set_first_as_default and not has_default_active and first_imported_address_lc:
        target = idx.get(first_imported_address_lc)
        if isinstance(target, dict) and target.get("status") == "active":
            # enforce at_most_one default among active
            for r in accounts:
                if isinstance(r, dict):
                    if r.get("status") == "active":
                        r["is_default"] = (r.get("id") == target.get("id"))
                        r["updated_at"] = now
                    else:
                        r["is_default"] = False
                        r["updated_at"] = now
