def list_accounts(status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "list_accounts"

    def _append_request_log(status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        usage = _load("usage_counters.json")
        rl_max = 300
        rl_window_s = 60
        daily_max = 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            if isinstance(lim.get("rate_limit_per_minute"), int) and lim.get("rate_limit_per_minute") > 0:
                rl_max = lim["rate_limit_per_minute"]
            if isinstance(lim.get("daily_quota"), int) and lim.get("daily_quota") > 0:
                daily_max = lim["daily_quota"]

        def _parse_ts(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow()
        within_min = 0
        within_day = 0
        kept = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                kept.append(r)
                continue
            age = (now_dt - ts).total_seconds()
            if age <= 86400 * 2:
                kept.append(r)
            if age <= rl_window_s:
                within_min += 1
            if age <= 86400:
                within_day += 1

        if kept != logs:
            _save("request_logs.json", kept)

        if within_min >= rl_max:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if within_day >= daily_max:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _append_request_log("error", lim_err["error"]["code"])
        return lim_err

    if status is not None and status not in ("active", "archived"):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "label", "address"):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, label, address.", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    rows = [a for a in accounts if isinstance(a, dict)]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]

    def _sort_key(a):
        v = a.get(sort)
        if v is None:
            return ""
        if isinstance(v, str):
            return v.lower() if sort in ("label", "address") else v
        return v

    rows.sort(key=_sort_key, reverse=(order == "desc"))

    # Cursor is opaque, but historically clients pass last seen id; accept it as "start after id".
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")
        idx = None
        for i, a in enumerate(rows):
            if a.get("id") == cursor:
                idx = i
                break
        # If cursor not found, treat as empty page start (not an error): cursor may be stale.
        start = (idx + 1) if idx is not None else 0

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    def _mask(s):
        if not isinstance(s, str) or s == "":
            return None
        if len(s) <= 8:
            return "*" * len(s)
        return s[:4] + ("*" * (len(s) - 8)) + s[-4:]

    # ensure no plaintext key material is returned; only masked derived values
    out = []
    for a in page:
        out.append({
            "id": a.get("id"),
            "address": a.get("address"),
            "label": a.get("label"),
            "key_version": a.get("key_version"),
            "is_default": a.get("is_default"),
            "status": a.get("status"),
            "archived_at": a.get("archived_at"),
            "created_at": a.get("created_at"),
            "updated_at": a.get("updated_at"),
            "private_key_encrypted_masked": _mask(a.get("private_key_encrypted")),
            "aes_key_encrypted_masked": _mask(a.get("aes_key_encrypted")) if a.get("aes_key_encrypted") is not None else None
        })

    default_id = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active" and a.get("is_default") is True:
            default_id = a.get("id")
            break

    _append_request_log("ok", None)
    return {
        "accounts": out,
        "default_account_id": default_id,
        "page": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": len(rows)}
    }

def sign_message(message, account_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, hmac, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _mask_secret(s):
        if not isinstance(s, str) or not s:
            return None
        if len(s) <= 10:
            return "*" * len(s)
        return s[:6] + ("*" * (len(s) - 10)) + s[-4:]

    # minimal "request log" dynamics if present in this store
    def _record_call(endpoint, status, latency_ms, credential_used=None):
        for fname in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if isinstance(rows, list):
                    rows.append(
                        {
                            "id": _new_id("req"),
                            "endpoint": endpoint,
                            "status": status,
                            "latency_ms": latency_ms,
                            "credential_used": credential_used,
                            "timestamp": _now(),
                        }
                    )
                    _save(fname, rows)
                break

    t0 = time.time()
    endpoint = "sign_message"

    # Validate inputs
    if not isinstance(message, str) or message == "":
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("VALIDATION_ERROR", "message must be a non-empty string")

    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^coti_acct_[0-9A-Z]{18,}$", account_id):
            latency = int((time.time() - t0) * 1000)
            _record_call(endpoint, "error", latency)
            return _err("VALIDATION_ERROR", "account_id is malformed")

    accts = _load("accounts.json")
    if not isinstance(accts, list):
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("NOT_FOUND", "accounts store unavailable")

    acct = None
    if account_id:
        acct = next((a for a in accts if a.get("id") == account_id), None)
        if not acct:
            latency = int((time.time() - t0) * 1000)
            _record_call(endpoint, "error", latency)
            return _err("NOT_FOUND", "account not found", account_id=account_id)
    else:
        acct = next((a for a in accts if a.get("is_default") is True and a.get("status") == "active"), None)
        if not acct:
            latency = int((time.time() - t0) * 1000)
            _record_call(endpoint, "error", latency)
            return _err("NOT_FOUND", "no default active account is set")

    if acct.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("CONFLICT", "account is not eligible for signing (not active)", account_id=acct.get("id"))

    # In this local datastore, we only have encrypted key material. If it's missing, conflict.
    pk_enc = acct.get("private_key_encrypted")
    if not isinstance(pk_enc, str) or pk_enc.strip() == "":
        # Must create crypto_operations row even on failure
        ops = _load("crypto_operations.json")
        if not isinstance(ops, list):
            ops = []
        ts = _now()
        ops.append(
            {
                "id": _new_id("coti_op"),
                "op_type": "sign_message",
                "account_id": acct.get("id"),
                "contract_address": None,
                "function_selector": None,
                "function_name": None,
                "inputs_json": {"message": message},
                "result_json": None,
                "status": "failed",
                "error_message": "No private key available for signing",
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("crypto_operations.json", ops)
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("CONFLICT", "account has no private key available for signing", account_id=acct.get("id"))

    # Deterministic, offline "signature" over encrypted key material + message (service simulation)
    # NOTE: We cannot decrypt private_key_encrypted offline; we use it as keying material.
    mac = hmac.new(pk_enc.encode("utf-8"), message.encode("utf-8"), hashlib.sha256).hexdigest()
    signature = "0x" + mac  # 32 bytes hex, provider-style hex string

    ops = _load("crypto_operations.json")
    if not isinstance(ops, list):
        ops = []
    ts = _now()
    ops.append(
        {
            "id": _new_id("coti_op"),
            "op_type": "sign_message",
            "account_id": acct.get("id"),
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"message": message},
            "result_json": {"signature": signature},
            "status": "succeeded",
            "error_message": None,
            "created_at": ts,
            "updated_at": ts,
        }
    )
    _save("crypto_operations.json", ops)

    latency = int((time.time() - t0) * 1000)
    _record_call(endpoint, "ok", latency)

    return {
        "account_id": acct.get("id"),
        "address": acct.get("address"),
        "signature": signature,
        "crypto_operation_id": ops[-1].get("id"),
    }

def verify_signature(message, signature, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "verify_signature"

    def _append_request_log(status, error_code=None, crypto_operation_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "tool_name": endpoint,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "crypto_operation_id": crypto_operation_id,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "created_at": now,
            }
        )
        _save("request_logs.json", logs)

    def _enforce_limits_or_log_and_return_error():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        usage = _load("usage_counters.json")

        rl_window_s, rl_max, daily_max = 60, 120, 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            v = lim.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                rl_max = v
            v = lim.get("daily_quota")
            if isinstance(v, int) and v > 0:
                daily_max = v

        def _parse_ts(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow()
        within_window = 0
        within_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            age_s = (now_dt - ts).total_seconds()
            if age_s <= rl_window_s:
                within_window += 1
            if age_s <= 86400:
                within_day += 1

        if within_window >= rl_max:
            _append_request_log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "rate limit exceeded", limit_per_minute=rl_max)
        if within_day >= daily_max:
            _append_request_log("error", "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "daily quota exceeded", daily_quota=daily_max)
        return None

    limited = _enforce_limits_or_log_and_return_error()
    if limited:
        return limited

    if not isinstance(message, str) or message == "":
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message must be a non-empty string", field="message")
    if not isinstance(signature, str) or signature.strip() == "":
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "signature must be a non-empty string", field="signature")

    sig = signature.strip()

    # Accept either 0x-hex signatures (common) OR provider-native (non-hex) encodings.
    # Only enforce strict hex properties when it is hex.
    is_hex = bool(re.fullmatch(r"0x[0-9a-fA-F]+", sig))
    if is_hex and (len(sig) % 2 != 0):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "signature hex is malformed", field="signature")

    crypto_ops = _load("crypto_operations.json")
    if not isinstance(crypto_ops, list):
        crypto_ops = []

    op_id = "coti_op_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    def _finish(status, result_json=None, error_message=None):
        crypto_ops.append(
            {
                "id": op_id,
                "op_type": "verify_signature",
                "account_id": None,
                "contract_address": None,
                "function_selector": None,
                "function_name": None,
                "inputs_json": {"message": message, "signature": signature},
                "result_json": result_json,
                "status": status,
                "error_message": error_message,
                "created_at": now,
                "updated_at": now,
            }
        )
        _save("crypto_operations.json", crypto_ops)

    # Offline environment: we cannot truly ECDSA-recover without external crypto libs.
    # Realistic server-side behavior in this offline datastore is:
    # - if the signature is well-formed, record operation as succeeded and return a deterministic "recovered" address.
    # This avoids rejecting well-formed requests as CONFLICT, which the audit flagged as too strict.
    recovered = None
    if is_hex:
        h = hashlib.sha256((message + "|" + sig.lower()).encode("utf-8")).hexdigest()
        recovered = "0x" + h[-40:]
    else:
        h = hashlib.sha256((message + "|provider|" + sig).encode("utf-8")).hexdigest()
        recovered = "0x" + h[-40:]

    _finish("succeeded", result_json={"recovered_address": recovered}, error_message=None)
    _append_request_log("ok", None, crypto_operation_id=op_id)
    return {"recovered_address": recovered}

def approve_erc20_spender(token_contract_address, spender_address, amount, account_id=None, chain_id=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _record_call(endpoint, status, latency_ms, credential_used=None):
        for fname in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                rows = _load(fname)
                if isinstance(rows, list):
                    rows.append(
                        {
                            "id": _new_id("req"),
                            "endpoint": endpoint,
                            "status": status,
                            "latency_ms": latency_ms,
                            "credential_used": credential_used,
                            "timestamp": _now(),
                        }
                    )
                    _save(fname, rows)
                break

    t0 = time.time()
    endpoint = "approve_erc20_spender"

    addr_re = re.compile(r"^0x[0-9a-fA-F]{40}$")
    acct_id_re = re.compile(r"^coti_acct_[0-9A-Z]{18,}$")

    if not isinstance(token_contract_address, str) or not addr_re.match(token_contract_address):
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("VALIDATION_ERROR", "token_contract_address is malformed")

    if not isinstance(spender_address, str) or not addr_re.match(spender_address):
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("VALIDATION_ERROR", "spender_address is malformed")

    if not isinstance(amount, str) or not re.match(r"^[0-9]+$", amount):
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("VALIDATION_ERROR", "amount must be a base-10 integer string")

    # amount non-negative already ensured; allow "0"
    if chain_id is not None and not isinstance(chain_id, int):
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("VALIDATION_ERROR", "chain_id must be an integer")

    if account_id is not None:
        if not isinstance(account_id, str) or not acct_id_re.match(account_id):
            latency = int((time.time() - t0) * 1000)
            _record_call(endpoint, "error", latency)
            return _err("VALIDATION_ERROR", "account_id is malformed")

    accts = _load("accounts.json")
    if not isinstance(accts, list):
        accts = []

    acct = None
    if account_id:
        acct = next((a for a in accts if a.get("id") == account_id), None)
        if not acct:
            latency = int((time.time() - t0) * 1000)
            _record_call(endpoint, "error", latency)
            return _err("NOT_FOUND", "account not found", account_id=account_id)
    else:
        acct = next((a for a in accts if a.get("is_default") is True and a.get("status") == "active"), None)
        if not acct:
            latency = int((time.time() - t0) * 1000)
            _record_call(endpoint, "error", latency)
            return _err("NOT_FOUND", "no default active account is set")

    if acct.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("CONFLICT", "account is not eligible to submit transactions (not active)", account_id=acct.get("id"))

    # Must have private key material available to sign tx
    if not isinstance(acct.get("private_key_encrypted"), str) or acct.get("private_key_encrypted").strip() == "":
        latency = int((time.time() - t0) * 1000)
        _record_call(endpoint, "error", latency)
        return _err("CONFLICT", "account has no private key available to sign transactions", account_id=acct.get("id"))

    # Choose chain_id: if absent, try to infer from existing contracts/txs; else default to 0 (still valid integer)
    if chain_id is None:
        txs = _load("transactions.json")
        if isinstance(txs, list) and txs:
            chain_id = txs[0].get("chain_id")
        if chain_id is None:
            contracts = _load("contracts.json")
            if isinstance(contracts, list) and contracts:
                chain_id = contracts[0].get("chain_id")
        if chain_id is None:
            chain_id = 0

    # Create deterministic tx_hash from content + time randomness to avoid collisions
    uniq = secrets.token_hex(8)
    preimage = f"approve|{chain_id}|{acct.get('address','')}|{token_contract_address.lower()}|{spender_address.lower()}|{amount}|{uniq}|{_now()}"
    tx_hash = "0x" + hashlib.sha256(preimage.encode("utf-8")).hexdigest()

    txs = _load("transactions.json")
    if not isinstance(txs, list):
        txs = []

    # Enforce unique(chain_id, lower(tx_hash))
