        dec = matches[0].get("decimals")
        if isinstance(dec, int):
            _append_request_log("ok", None)
            return {"chain_id": chain_id, "token_contract_address": token_contract_address, "decimals": dec}

    # offline fallback: typical ERC20 default
    _append_request_log("ok", None)
    return {"chain_id": chain_id, "token_contract_address": token_contract_address, "decimals": 18}

