def mint_private_erc20_token(contract_address, to_address, amount, account_id=None, chain_id=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "mint_private_erc20_token"

    def _append_request_log(status, error_code=None, transaction_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "transaction_id": transaction_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "created_at": now
        })
        _save("request_logs.json", logs)

    addr_re = re.compile(r"^0x[0-9a-fA-F]{40}$")
    acct_id_re = re.compile(r"^coti_acct_[0-9A-Z]{18,}$")
    dec_re = re.compile(r"^[0-9]+$")

    if not isinstance(contract_address, str) or not addr_re.match(contract_address):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed contract_address.", field="contract_address")
    if not isinstance(to_address, str) or not addr_re.match(to_address):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed to_address.", field="to_address")
    if not isinstance(amount, str) or not dec_re.match(amount):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "amount must be a non-negative base-10 integer string.", field="amount")
    try:
        if int(amount) < 0:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "amount must be non-negative.", field="amount")
    except Exception:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "amount must be a base-10 integer string.", field="amount")

    if chain_id is not None and not isinstance(chain_id, int):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chain_id must be an integer when provided.", field="chain_id")
    if account_id is not None and (not isinstance(account_id, str) or not acct_id_re.match(account_id)):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    transactions = _load("transactions.json")
    if not isinstance(transactions, list):
        transactions = []
    contracts = _load("contracts.json")
    if not isinstance(contracts, list):
        contracts = []

    def _resolve_account():
        if account_id is not None:
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id:
                    return a
            return None
        defaults = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("is_default") is True]
        return defaults[0] if defaults else next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active"), None)

    acct = _resolve_account()
    if not acct:
        _append_request_log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active local account is available to sign this transaction.")

    if acct.get("status") != "active":
        _append_request_log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Account is not active.", account_id=acct.get("id"))

    # locate contract record if possible (optional)
    ctr = None
    for c in contracts:
        if isinstance(c, dict) and isinstance(c.get("address"), str) and c.get("address").lower() == contract_address.lower():
            if chain_id is None or c.get("chain_id") == chain_id:
                ctr = c
                break

    # create pending tx with unique tx_hash per chain_id
    effective_chain = chain_id if isinstance(chain_id, int) else (ctr.get("chain_id") if isinstance(ctr, dict) and isinstance(ctr.get("chain_id"), int) else 7082400)
    seed = f"mint|{effective_chain}|{contract_address.lower()}|{to_address.lower()}|{amount}|{acct.get('id')}|{time.time_ns()}"
    tx_hash = "0x" + hashlib.sha256(seed.encode("utf-8")).hexdigest()

    for tx in transactions:
        if isinstance(tx, dict) and tx.get("chain_id") == effective_chain and isinstance(tx.get("tx_hash"), str) and tx.get("tx_hash").lower() == tx_hash.lower():
            # idempotent retry: return existing hash (but must not create new row)
            _append_request_log("ok", None, transaction_id=tx.get("id"))
            return {"chain_id": effective_chain, "tx_hash": tx.get("tx_hash"), "transaction_id": tx.get("id")}

    tx_id = "coti_tx_" + hashlib.sha256(f"tx|{time.time_ns()}|{os.urandom(8).hex()}".encode("utf-8")).hexdigest()[:24]
    tx_row = {
        "id": tx_id,
        "chain_id": effective_chain,
        "tx_hash": tx_hash,
        "initiator_account_id": acct.get("id"),
        "tool_name": endpoint,
        "tx_type": "private_erc20_mint",
        "to_address": contract_address,
        "contract_id": ctr.get("id") if isinstance(ctr, dict) else None,
        "value_wei": None,
        "function_selector": "0x40c10f19",
        "call_data_hex": None,
        "inputs_json": {"contract_address": contract_address, "to_address": to_address, "amount": amount},
        "submitted_at": now,
        "mined_at": None,
        "block_number": None,
        "status": "pending",
        "failure_reason": None,
        "created_at": now,
        "updated_at": now
    }
    transactions.append(tx_row)
    _save("transactions.json", transactions)
    _append_request_log("ok", None, transaction_id=tx_id)
    return {"chain_id": effective_chain, "tx_hash": tx_hash, "transaction_id": tx_id}

def transfer_private_erc20(contract_address, to_address, amount, account_id=None, chain_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "transfer_private_erc20"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(ts):
        try:
            if isinstance(ts, str) and ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
        except Exception:
            return None

    def _limits():
        usage = _load("usage_counters.json")
        rl_window_s, rl_max, daily_max = 60, 120, 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            v = lim.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                rl_max = v
            v = lim.get("daily_quota")
            if isinstance(v, int) and v > 0:
                daily_max = v
        return rl_window_s, rl_max, daily_max

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rl_window_s, rl_max, daily_max = _limits()
        within_window = 0
        within_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= rl_window_s:
                within_window += 1
            if ts.date() == now_dt.date():
                within_day += 1
        if within_window >= rl_max:
            return _err("RATE_LIMIT", f"Rate limit exceeded: max {rl_max} requests per {rl_window_s} seconds.", limit=rl_max, window_seconds=rl_window_s)
        if within_day >= daily_max:
            return _err("QUOTA_EXCEEDED", f"Daily quota exceeded: max {daily_max} requests per day.", limit=daily_max)
        return None

    def _append_request_log(status, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rec = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "created_at": now,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if isinstance(extra, dict):
            rec.update(extra)
        logs.append(rec)
        _save("request_logs.json", logs)

        usage = _load("usage_counters.json")
        if not isinstance(usage, dict):
            usage = {}
        usage.setdefault("counters", {})
        usage["counters"]["requests_total"] = int(usage["counters"].get("requests_total", 0) or 0) + 1
        usage["counters"]["requests_" + endpoint] = int(usage["counters"].get("requests_" + endpoint, 0) or 0) + 1
        if status != "ok":
            usage["counters"]["errors_total"] = int(usage["counters"].get("errors_total", 0) or 0) + 1
        usage["updated_at"] = now
        _save("usage_counters.json", usage)

    # Rate/quota enforcement (must log even on refusal)
    lim_err = _enforce_limits()
    if lim_err:
        _append_request_log("err", lim_err["error"]["code"])
        return lim_err

    try:
        if not isinstance(contract_address, str) or not contract_address:
            e = _err("VALIDATION_ERROR", "contract_address is required and must be a string.", field="contract_address")
            _append_request_log("err", e["error"]["code"])
            return e
        if not isinstance(to_address, str) or not to_address:
            e = _err("VALIDATION_ERROR", "to_address is required and must be a string.", field="to_address")
            _append_request_log("err", e["error"]["code"])
            return e
        if not isinstance(amount, str) or not amount:
            e = _err("VALIDATION_ERROR", "amount is required and must be a base-10 integer string.", field="amount")
            _append_request_log("err", e["error"]["code"])
            return e

        addr_re = re.compile(r"^0x[0-9a-fA-F]{40}$")
        if not addr_re.match(contract_address):
            e = _err("VALIDATION_ERROR", "contract_address must be a 0x-prefixed 20-byte hex address.", field="contract_address")
            _append_request_log("err", e["error"]["code"])
            return e
        if not addr_re.match(to_address):
            e = _err("VALIDATION_ERROR", "to_address must be a 0x-prefixed 20-byte hex address.", field="to_address")
            _append_request_log("err", e["error"]["code"])
            return e

        # amount: positive base-10 integer string (per tool description)
        if not re.fullmatch(r"[0-9]+", amount or ""):
            e = _err("VALIDATION_ERROR", "amount must be a positive base-10 integer string.", field="amount")
            _append_request_log("err", e["error"]["code"])
            return e
        try:
            amt_i = int(amount, 10)
        except ValueError:
            e = _err("VALIDATION_ERROR", "amount must be a positive base-10 integer string.", field="amount")
            _append_request_log("err", e["error"]["code"])
            return e
        if amt_i <= 0:
            e = _err("VALIDATION_ERROR", "amount must be a positive integer greater than 0.", field="amount")
            _append_request_log("err", e["error"]["code"])
            return e

        if account_id is not None:
            if not isinstance(account_id, str) or not re.fullmatch(r"^coti_acct_[0-9A-Z]{18,}$", account_id):
                e = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
                _append_request_log("err", e["error"]["code"])
                return e
        if chain_id is not None and not isinstance(chain_id, int):
            e = _err("VALIDATION_ERROR", "chain_id must be an integer.", field="chain_id")
            _append_request_log("err", e["error"]["code"])
            return e

        accounts = _load("accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        contracts = _load("contracts.json")
        if not isinstance(contracts, list):
            contracts = []
        txs = _load("transactions.json")
        if not isinstance(txs, list):
            txs = []

        # Resolve signer account: explicit active account, else default active.
        signer = None
        if account_id:
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id and a.get("status") == "active":
                    signer = a
                    break
            if signer is None:
                e = _err("NOT_FOUND", "No active account exists with the given account_id.", account_id=account_id)
                _append_request_log("err", e["error"]["code"])
                return e
        else:
            for a in accounts:
                if isinstance(a, dict) and a.get("status") == "active" and a.get("is_default") is True:
                    signer = a
                    break
            if signer is None:
                # fall back to any active account (ambient auth should not refuse a well-formed call unnecessarily)
                for a in accounts:
                    if isinstance(a, dict) and a.get("status") == "active":
                        signer = a
                        break
            if signer is None:
                e = _err("UNAUTHORIZED", "No active local account is available to sign the transaction.")
                _append_request_log("err", e["error"]["code"])
                return e

        # Resolve chain_id:
        effective_chain_id = chain_id
        if effective_chain_id is None:
            # Prefer chain_id from an existing contract record with this address; else from any existing transaction; else validation error.
            ca_l = contract_address.lower()
            for c in contracts:
                if isinstance(c, dict) and isinstance(c.get("address"), str) and c.get("address").lower() == ca_l:
                    if isinstance(c.get("chain_id"), int):
                        effective_chain_id = c["chain_id"]
                        break
            if effective_chain_id is None:
                for t in txs:
                    if isinstance(t, dict) and isinstance(t.get("chain_id"), int):
                        effective_chain_id = t["chain_id"]
                        break
        if effective_chain_id is None:
            e = _err("VALIDATION_ERROR", "chain_id is required because no default chain context could be inferred.", field="chain_id")
            _append_request_log("err", e["error"]["code"])
            return e

        # Contract record is OPTIONAL for submission; if present, it should match chain/address and preferably be a private_erc20.
        contract_row = None
        ca_l = contract_address.lower()
        for c in contracts:
            if not isinstance(c, dict):
                continue
            if c.get("chain_id") == effective_chain_id and isinstance(c.get("address"), str) and c.get("address").lower() == ca_l:
                # If multiple exist (shouldn't), prefer active + private_erc20
                if contract_row is None:
                    contract_row = c
                else:
                    def _score(x):
                        s = 0
                        if x.get("status") == "active": s += 2
                        if x.get("contract_type") == "private_erc20": s += 3
                        return s
                    if _score(c) > _score(contract_row):
                        contract_row = c

        # If found but wrong type, treat as validation error (caller likely routed wrongly)
        if contract_row is not None and contract_row.get("contract_type") not in ("private_erc20", "generic"):
            e = _err(
                "VALIDATION_ERROR",
                "Contract record exists but is not compatible with private ERC20 transfer (expected contract_type 'private_erc20' or 'generic').",
                contract_address=contract_address,
                chain_id=effective_chain_id,
                contract_type=contract_row.get("contract_type"),
            )
            _append_request_log("err", e["error"]["code"])
            return e

        # Create pending transaction (must have effect)
        def _new_id(prefix):
            return prefix + hashlib.sha256(f"{prefix}|{time.time_ns()}|{secrets.token_hex(8)}".encode("utf-8")).hexdigest()[:26]

        tx_hash = "0x" + secrets.token_hex(32)
        # enforce unique(chain_id, lower(tx_hash))
        txh_l = tx_hash.lower()
        for t in txs:
            if isinstance(t, dict) and t.get("chain_id") == effective_chain_id and isinstance(t.get("tx_hash"), str) and t["tx_hash"].lower() == txh_l:
                # extremely unlikely; regenerate once
                tx_hash = "0x" + secrets.token_hex(32)
                txh_l = tx_hash.lower()
                break

        tx_id = _new_id("coti_tx_")
        tx_row = {
            "id": tx_id,
            "chain_id": effective_chain_id,
            "tx_hash": tx_hash,
            "initiator_account_id": signer.get("id"),
            "tool_name": endpoint,
            "tx_type": "private_erc20_transfer",
            "to_address": contract_address,  # contract interaction destination
            "contract_id": contract_row.get("id") if isinstance(contract_row, dict) else None,
            "value_wei": "0",
            "function_selector": "0xa9059cbb",
            "call_data_hex": None,
            "inputs_json": {
                "contract_address": contract_address,
                "to_address": to_address,
                "amount": amount,
                "account_id": signer.get("id"),
                "chain_id": effective_chain_id,
            },
            "submitted_at": now,
            "mined_at": None,
            "block_number": None,
            "status": "pending",
            "failure_reason": None,
            "created_at": now,
            "updated_at": now,
        }

        txs.append(tx_row)
        _save("transactions.json", txs)

        _append_request_log("ok", extra={"transaction_id": tx_id, "tx_hash": tx_hash})
        return {
            "transaction": tx_row,
            "tx_hash": tx_hash,
        }
    except Exception as e:
        err = _err("VALIDATION_ERROR", "Unexpected error while processing transfer_private_erc20.", detail=str(e))
        _append_request_log("err", err["error"]["code"])
        return err

