        return _err("VALIDATION_ERROR", "token_id must be a non-negative base-10 integer string.", field="token_id")
    try:
        if int(token_id) < 0:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "token_id must be non-negative.", field="token_id")
    except Exception:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "token_id must be a base-10 integer string.", field="token_id")

    if chain_id is not None and not isinstance(chain_id, int):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chain_id must be an integer when provided.", field="chain_id")
    if account_id is not None and (not isinstance(account_id, str) or not acct_id_re.match(account_id)):
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    transactions = _load("transactions.json")
    if not isinstance(transactions, list):
        transactions = []
    contracts = _load("contracts.json")
    if not isinstance(contracts, list):
        contracts = []

    def _resolve_account():
        if account_id is not None:
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id:
                    return a
            return None
        defaults = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("is_default") is True]
        return defaults[0] if defaults else next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active"), None)

    acct = _resolve_account()
    if not acct:
        _append_request_log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active local account is available to sign this transaction.")

    # locate contract record if possible
    ctr = None
    for c in contracts:
        if isinstance(c, dict) and isinstance(c.get("address"), str) and c.get("address").lower() == contract_address.lower() and c.get("status") == "active":
            if chain_id is None or c.get("chain_id") == chain_id:
                ctr = c
                break

    effective_chain = chain_id if isinstance(chain_id, int) else (ctr.get("chain_id") if isinstance(ctr, dict) and isinstance(ctr.get("chain_id"), int) else 7082400)
    seed = f"approve721|{effective_chain}|{contract_address.lower()}|{spender_address.lower()}|{token_id}|{acct.get('id')}|{time.time_ns()}"
    tx_hash = "0x" + hashlib.sha256(seed.encode("utf-8")).hexdigest()

    for tx in transactions:
        if isinstance(tx, dict) and tx.get("chain_id") == effective_chain and isinstance(tx.get("tx_hash"), str) and tx.get("tx_hash").lower() == tx_hash.lower():
            _append_request_log("ok", None, transaction_id=tx.get("id"))
            return {"chain_id": effective_chain, "tx_hash": tx.get("tx_hash"), "transaction_id": tx.get("id")}

    tx_id = "coti_tx_" + hashlib.sha256(f"tx|{time.time_ns()}|{os.urandom(8).hex()}".encode("utf-8")).hexdigest()[:24]
    tx_row = {
        "id": tx_id,
        "chain_id": effective_chain,
        "tx_hash": tx_hash,
        "initiator_account_id": acct.get("id"),
        "tool_name": endpoint,
        "tx_type": "erc721_approve",
        "to_address": contract_address,
        "contract_id": ctr.get("id") if isinstance(ctr, dict) else None,
        "value_wei": None,
        "function_selector": "0x095ea7b3",
        "call_data_hex": None,
        "inputs_json": {"contract_address": contract_address, "spender_address": spender_address, "token_id": token_id},
        "submitted_at": now,
        "mined_at": None,
        "block_number": None,
        "status": "pending",
        "failure_reason": None,
        "created_at": now,
        "updated_at": now
    }
    transactions.append(tx_row)
    _save("transactions.json", transactions)
    _append_request_log("ok", None, transaction_id=tx_id)
    return {"chain_id": effective_chain, "tx_hash": tx_hash, "transaction_id": tx_id}

def deploy_private_erc721_contract(name, symbol, account_id=None, chain_id=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    accounts = _load("accounts.json")
    contracts = _load("contracts.json")
    transactions = _load("transactions.json")
    reqlog = _load("request_logs.json")
    usage = _load("usage_counters.json")

    endpoint = "deploy_private_erc721_contract"

    # rate/quota
    def _get_limits():
        rl_window_s, rl_max, daily_max = 60, 60, 1000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            v = lim.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0: rl_max = v
            v = lim.get("daily_quota")
            if isinstance(v, int) and v > 0: daily_max = v
        return rl_window_s, rl_max, daily_max

    def _parse_ts(ts):
        try:
            if isinstance(ts, str) and ts.endswith("Z"): ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    rl_window_s, rl_max, daily_max = _get_limits()
    kept = []
    last_min = 0
    day_cnt = 0
    for r in reqlog if isinstance(reqlog, list) else []:
        ts = _parse_ts(r.get("timestamp")) if isinstance(r, dict) else None
        if ts and (now_dt - ts).total_seconds() <= 86400 * 2:
            kept.append(r)
        elif not ts:
            kept.append(r)
        if ts and (now_dt - ts).total_seconds() <= rl_window_s:
            last_min += 1
        if ts and ts.date() == now_dt.date():
            day_cnt += 1
    if last_min >= rl_max:
        if isinstance(reqlog, list):
            reqlog = kept
            reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "RATE_LIMIT", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
            _save("request_logs.json", reqlog)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if day_cnt >= daily_max:
        if isinstance(reqlog, list):
            reqlog = kept
            reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
            _save("request_logs.json", reqlog)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # validate
    if not isinstance(name, str) or not name.strip():
        if isinstance(reqlog, list):
            reqlog = kept
            reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if not isinstance(symbol, str) or not symbol.strip():
        if isinstance(reqlog, list):
            reqlog = kept
            reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    if chain_id is not None and not isinstance(chain_id, int):
        if isinstance(reqlog, list):
            reqlog = kept
            reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "chain_id must be an integer when provided")
    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^coti_acct_[0-9A-Z]{18,}$", account_id):
            if isinstance(reqlog, list):
                reqlog = kept
                reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", "account_id is malformed")

    # resolve account
    acct = None
    if account_id:
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acct = a
                break
        if not acct:
            if isinstance(reqlog, list):
                reqlog = kept
                reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
                _save("request_logs.json", reqlog)
            return _err("NOT_FOUND", "account_id not found")
        if acct.get("status") != "active":
            if isinstance(reqlog, list):
                reqlog = kept
                reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "INVALID_TRANSITION", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
                _save("request_logs.json", reqlog)
            return _err("INVALID_TRANSITION", "account is not active")
    else:
        for a in accounts:
            if isinstance(a, dict) and a.get("is_default") is True and a.get("status") == "active":
                acct = a
                break
        if not acct:
            if isinstance(reqlog, list):
                reqlog = kept
                reqlog.append({"id": f"req_{secrets.token_hex(8)}", "endpoint": endpoint, "status": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
                _save("request_logs.json", reqlog)
            return _err("UNAUTHORIZED", "No active default account available")

    resolved_chain_id = chain_id if chain_id is not None else 0

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    # Create pending deployment transaction (always required by business rules)
    seed = f"{resolved_chain_id}|{endpoint}|{acct.get('address')}|{name}|{symbol}|{secrets.token_hex(8)}".encode("utf-8")
    tx_hash = "0x" + hashlib.sha256(seed).hexdigest()

    # uniqueness per chain_id
    if any(isinstance(t, dict) and t.get("chain_id") == resolved_chain_id and isinstance(t.get("tx_hash"), str) and t["tx_hash"].lower() == tx_hash.lower() for t in transactions):
        seed = f"{seed!r}|{secrets.token_hex(8)}".encode("utf-8")
        tx_hash = "0x" + hashlib.sha256(seed).hexdigest()
    if any(isinstance(t, dict) and t.get("chain_id") == resolved_chain_id and isinstance(t.get("tx_hash"), str) and t["tx_hash"].lower() == tx_hash.lower() for t in transactions):
        if isinstance(reqlog, list):
            reqlog = kept
            reqlog.append({"id": _new_id("req"), "endpoint": endpoint, "status": "CONFLICT", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
            _save("request_logs.json", reqlog)
        return _err("CONFLICT", "tx_hash uniqueness conflict, please retry")

    tx_id = _new_id("coti_tx")
    tx_row = {
        "id": tx_id,
        "chain_id": resolved_chain_id,
        "tx_hash": tx_hash,
        "initiator_account_id": acct["id"],
        "tool_name": endpoint,
        "tx_type": "deploy_contract",
        "to_address": None,
        "contract_id": None,
        "value_wei": None,
        "function_selector": None,
        "call_data_hex": None,
        "inputs_json": {"name": name, "symbol": symbol, "contract_type": "private_erc721"},
        "submitted_at": now,
        "mined_at": None,
        "block_number": None,
        "status": "pending",
        "failure_reason": None,
        "created_at": now,
        "updated_at": now
    }
    transactions.append(tx_row)
    _save("transactions.json", transactions)

    # In a real network we only know contract address after mining; here we deterministically derive a "predicted"
    # contract address for client convenience, but we only record a contracts row when confirmed (business rule).
    predicted = "0x" + hashlib.sha256(f"coti|{resolved_chain_id}|{tx_hash}".encode("utf-8")).hexdigest()[:40]

    # request log + usage
    if isinstance(reqlog, list):
        reqlog = kept
        reqlog.append({"id": _new_id("req"), "endpoint": endpoint, "status": "OK", "timestamp": now, "latency_ms": int((time.time()-_t0)*1000), "credential_id": None})
        _save("request_logs.json", reqlog)
    if isinstance(usage, dict):
        usage.setdefault("by_endpoint", {})
        usage["by_endpoint"][endpoint] = int(usage["by_endpoint"].get(endpoint, 0)) + 1
        usage["total_calls"] = int(usage.get("total_calls", 0)) + 1
        _save("usage_counters.json", usage)

    return {
        "transaction_hash": tx_hash,
        "predicted_contract_address": predicted,
        "transaction": {k: v for k, v in tx_row.items() if k not in ("call_data_hex",)},
        "contract_record_created": False
    }

def get_private_erc721_approved(contract_address, token_id, account_id=None, chain_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers
    def _log(status, used_account_id=None, error_code=None, error_message=None, extra=None):
        logs = _load("crypto_operations.json")
        op_id = "coti_cop_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + ("%016x" % random.getrandbits(64))
        row = {
            "id": op_id,
            "op_type": "call_contract_function",
            "account_id": used_account_id,
            "contract_address": contract_address,
            "function_selector": "0x081812fc",  # getApproved(uint256)
            "function_name": "getApproved",
            "inputs_json": {
                "contract_address": contract_address,
                "token_id": token_id,
                "chain_id": chain_id
            },
            "result_json": extra.get("result_json") if extra else None,
            "status": "succeeded" if status == "succeeded" else "failed",
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("crypto_operations.json", logs)
        latency_ms = int((time.time() - t0) * 1000)
        if status == "succeeded":
            return {"operation_id": op_id, "status": "succeeded", "latency_ms": latency_ms}
        return {"operation_id": op_id, "status": "failed", "latency_ms": latency_ms, "error": {"code": error_code or "RPC_ERROR", "message": error_message or "Call failed"}}

    def _is_addr(a):
        return isinstance(a, str) and re.fullmatch(r"^0x[0-9a-fA-F]{40}$", a or "") is not None

    def _is_u256_dec(s):
        return isinstance(s, str) and re.fullmatch(r"^(0|[1-9][0-9]*)$", s) is not None

    def _resolve_account(accts, wanted_id):
        if wanted_id is not None:
            if not isinstance(wanted_id, str) or re.fullmatch(r"^coti_acct_[0-9A-Z]{18,}$", wanted_id) is None:
                return None, _err("VALIDATION_ERROR", "account_id is malformed")
            for a in accts:
                if a.get("id") == wanted_id:
                    return a, None
            return None, _err("NOT_FOUND", "account_id not found")
        # default active
        for a in accts:
            if a.get("status") == "active" and a.get("is_default") is True:
                return a, None
        # fallback any active
        for a in accts:
            if a.get("status") == "active":
                return a, None
        return None, _err("UNAUTHORIZED", "No active account context available")

    def _default_chain_id(contracts, txs):
        # Prefer any chain_id present in contracts/txs, else 130 (common COTI testnet/mainnet vary; offline fallback)
        for c in contracts:
            if isinstance(c.get("chain_id"), int):
                return c["chain_id"]
        for tx in txs:
            if isinstance(tx.get("chain_id"), int):
                return tx["chain_id"]
        return 130

    # --- validate required
    if not _is_addr(contract_address):
        return _log("failed", used_account_id=account_id, error_code="VALIDATION_ERROR",
                    error_message="contract_address must match ^0x[0-9a-fA-F]{40}$")
    if not _is_u256_dec(token_id):
        return _log("failed", used_account_id=account_id, error_code="VALIDATION_ERROR",
                    error_message="token_id must be a non-negative base-10 string")

    if chain_id is not None and not isinstance(chain_id, int):
        return _log("failed", used_account_id=account_id, error_code="VALIDATION_ERROR",
                    error_message="chain_id must be an integer")

    accts = _load("accounts.json")
    contracts = _load("contracts.json")
    txs = _load("transactions.json")

    acct, e = _resolve_account(accts, account_id)
    if e:
        # do not create succeeded op; still record failed op per "records the read result / persisted history"
        return _log("failed", used_account_id=account_id, error_code=e["error"]["code"], error_message=e["error"]["message"])

    eff_chain_id = chain_id if chain_id is not None else _default_chain_id(contracts, txs)

    # If contract exists locally and has chain_id, enforce chain match when chain_id provided/derived
    for c in contracts:
        if c.get("status") == "active" and isinstance(c.get("address"), str) and c["address"].lower() == contract_address.lower():
            if isinstance(c.get("chain_id"), int) and c["chain_id"] != eff_chain_id:
                return _log("failed", used_account_id=acct.get("id"), error_code="VALIDATION_ERROR",
                            error_message="chain_id does not match local contract record")
            break

    # Offline deterministic placeholder for "read call":
    # Since no chain RPC is modeled in datastore, produce stable pseudo-result for repeatable reads.
    h = hashlib.sha256((str(eff_chain_id) + "|" + contract_address.lower() + "|getApproved|" + token_id).encode("utf-8")).hexdigest()
    approved = "0x" + h[:40]
    # Some calls can reasonably return zero address; make it deterministic 1/8 of the time.
    if int(h[-2:], 16) % 8 == 0:
        approved = "0x" + ("0" * 40)

    result = {
        "chain_id": eff_chain_id,
        "contract_address": contract_address,
        "token_id": token_id,
        "approved_address": approved
    }
    op_meta = _log("succeeded", used_account_id=acct.get("id"), extra={"result_json": result})
    return {"approved_address": approved, "chain_id": eff_chain_id, "operation_id": op_meta["operation_id"], "latency_ms": op_meta["latency_ms"]}

