def mint_private_erc721_token(contract_address, to_address, token_uri, account_id=None, chain_id=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    accounts = _load("accounts.json")
    contracts = _load("contracts.json")
    txs = _load("transactions.json")
    logs = _load("transaction_logs.json")

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        s = "".join(secrets.choice(alphabet) for _ in range(22))
        return f"{prefix}_{s}"

    def _is_addr(a):
        return isinstance(a, str) and re.fullmatch(r"^0x[0-9a-fA-F]{40}$", a or "") is not None

    def _tx_hash():
        return "0x" + secrets.token_hex(32)

    def _find_account(acct_id):
        if acct_id is not None:
            if not isinstance(acct_id, str) or re.fullmatch(r"^coti_acct_[0-9A-Z]{18,}$", acct_id) is None:
                return ("VALIDATION_ERROR", "account_id is invalid.", None)
            for a in accounts:
                if a.get("id") == acct_id:
                    if a.get("status") != "active":
                        return ("UNAUTHORIZED", "Selected local account is not active.", None)
                    return (None, None, a)
            return ("NOT_FOUND", "account_id is not a locally-managed account.", None)
        defaults = [a for a in accounts if a.get("status") == "active" and a.get("is_default") is True]
        if not defaults:
            return ("NOT_FOUND", "No default account is set.", None)
        return (None, None, defaults[0])

    # Validate inputs
    if not _is_addr(contract_address):
        return _err("VALIDATION_ERROR", "contract_address is missing or invalid.")
    if not _is_addr(to_address):
        return _err("VALIDATION_ERROR", "to_address is missing or invalid.")
    if not isinstance(token_uri, str) or token_uri == "":
        return _err("VALIDATION_ERROR", "token_uri is missing or invalid.")
    if chain_id is not None and not isinstance(chain_id, int):
        return _err("VALIDATION_ERROR", "chain_id must be an integer.")

    code, msg, acct = _find_account(account_id)
    if code:
        return _err(code, msg)
    initiator_id = acct.get("id")

    # Ensure contract exists/active or allow unknown contract but still validate as private_erc721 if present
    contract_row = None
    for c in contracts:
        if isinstance(c.get("address"), str) and c.get("address").lower() == contract_address.lower() and c.get("status") == "active":
            if chain_id is None or c.get("chain_id") == chain_id:
                contract_row = c
                break

    # Create pending transaction record with unique tx_hash per chain_id
    desired_chain_id = chain_id if chain_id is not None else (contract_row.get("chain_id") if contract_row else 0)
    # generate unique hash
    for _ in range(10):
        h = _tx_hash()
        dup = False
        for t in txs:
            if t.get("chain_id") == desired_chain_id and isinstance(t.get("tx_hash"), str) and t.get("tx_hash").lower() == h.lower():
                dup = True
                break
        if not dup:
            tx_hash = h
            break
    else:
        return _err("CONFLICT", "Unable to generate unique tx_hash; please retry.")

    ts = _now()
    tx_id = _gen_id("coti_tx")
    contract_id = contract_row.get("id") if contract_row else None

    # pseudo function selector for mint(to,tokenURI)
    selector = "0x" + hashlib.sha256(b"mint(address,string)").hexdigest()[:8]

    tx_row = {
        "id": tx_id,
        "chain_id": desired_chain_id,
        "tx_hash": tx_hash,
        "initiator_account_id": initiator_id,
        "tool_name": "mint_private_erc721_token",
        "tx_type": "private_erc721_mint",
        "to_address": contract_address,  # contract interactions store contract address here
        "contract_id": contract_id,
        "value_wei": "0",
        "function_selector": selector,
        "call_data_hex": None,
        "inputs_json": {"contract_address": contract_address, "to_address": to_address, "token_uri": token_uri},
        "submitted_at": ts,
        "mined_at": None,
        "block_number": None,
        "status": "pending",
        "failure_reason": None,
        "created_at": ts,
        "updated_at": ts
    }

    txs.append(tx_row)
    _save("transactions.json", txs)

    # Best-effort decode minted token id from a synthetic log and upsert it.
    # We cannot confirm/mine here, so logs are "raw" and mined info is absent.
    # Still, record a deterministic token_id for audit/reconciliation.
    token_id = str(int(hashlib.sha256((tx_hash + "|" + to_address.lower()).encode("utf-8")).hexdigest()[:12], 16))
    transfer_sig = "Transfer(address,address,uint256)"
    topic0 = "0x" + hashlib.sha256(transfer_sig.encode("utf-8")).hexdigest()
    # topics: [sig, from(0), to, tokenId]
    def _topic_addr(a):
        return "0x" + ("0" * 24) + a[2:].lower()
    def _topic_uint(u_str):
        n = int(u_str)
        hx = hex(n)[2:]
        return "0x" + hx.rjust(64, "0")

    tx_log_key = (tx_id, 0)
    existing = None
    for lg in logs:
        if lg.get("transaction_id") == tx_log_key[0] and lg.get("log_index") == tx_log_key[1]:
            existing = lg
            break
    if existing is None:
        log_id = _gen_id("coti_log")
        logs.append({
            "id": log_id,
            "transaction_id": tx_id,
            "log_index": 0,
            "emitter_address": contract_address,
            "topics": [topic0, _topic_addr("0x" + "0"*40), _topic_addr(to_address), _topic_uint(token_id)],
            "data": "0x",
            "event_signature": transfer_sig,
            "event_name": None,
            "decoded_args_json": None,
            "decode_status": "raw",
            "created_at": ts,
            "updated_at": ts
        })
        _save("transaction_logs.json", logs)

    return {
        "transaction": {
            "id": tx_id,
            "chain_id": desired_chain_id,
            "tx_hash": tx_hash,
            "status": "pending",
            "submitted_at": ts
        },
        "mint": {
            "to_address": to_address,
            "token_id": token_id,
            "token_uri": token_uri
        }
    }

