                    r["status"] = "succeeded"
                    r["latency_ms"] = int((time.time() - t0) * 1000)
                    break
            _save(req_file, logs2)
        return body

    def _finish_err(e):
        logs2 = _load(req_file)
        if isinstance(logs2, list):
            for r in reversed(logs2):
                if isinstance(r, dict) and r.get("id") == req_id:
