    if not isinstance(to_address, str) or not re.fullmatch(r"^0x[0-9a-fA-F]{40}$", to_address or ""):
        return _finish_err(_err("VALIDATION_ERROR", "to_address must be a 0x-prefixed 20-byte hex address."))
    if not isinstance(token_id, str) or token_id == "" or not re.fullmatch(r"^[0-9]+$", token_id):
        return _finish_err(_err("VALIDATION_ERROR", "token_id must be a non-negative integer string."))
    if chain_id is not None and not isinstance(chain_id, int):
        return _finish_err(_err("VALIDATION_ERROR", "chain_id must be an integer when provided."))
    if account_id is not None:
        if not isinstance(account_id, str) or not re.fullmatch(r"^coti_acct_[0-9A-Z]{18,}$", account_id):
            return _finish_err(_err("VALIDATION_ERROR", "account_id must match ^coti_acct_[0-9A-Z]{18,}$."))

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Resolve signing account: explicit or default active
    acct = None
    if account_id is not None:
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acct = a
                break
        if acct is None:
            return _finish_err(_err("NOT_FOUND", "Signing account_id not found.", account_id=account_id))
        if acct.get("status") != "active":
            return _finish_err(_err("INVALID_TRANSITION", "Signing account is not active.", account_id=account_id, status=acct.get("status")))
    else:
        for a in accounts:
            if isinstance(a, dict) and a.get("is_default") is True and a.get("status") == "active":
                acct = a
                break
        if acct is None:
            return _finish_err(_err("NOT_FOUND", "No default active account is set."))

    # Resolve known contract record if exists (not required to submit, but if present ensure chain_id consistency)
    contracts = _load("contracts.json")
    if not isinstance(contracts, list):
        contracts = []
    contract_row = None
    for c in contracts:
        if not isinstance(c, dict):
            continue
        if (c.get("address") or "").lower() == contract_address.lower() and c.get("status") == "active":
            if chain_id is None or c.get("chain_id") == chain_id:
                contract_row = c
                break
    # If contract found but chain_id missing, inherit
    if chain_id is None and contract_row is not None and isinstance(contract_row.get("chain_id"), int):
        chain_id = contract_row["chain_id"]
    # If still missing, choose a reasonable default chain_id from any existing contract/tx; else 0 (must be int)
    if chain_id is None:
        txs = _load("transactions.json")
        if isinstance(txs, list):
            for tx in txs:
                if isinstance(tx, dict) and isinstance(tx.get("chain_id"), int):
                    chain_id = tx["chain_id"]
                    break
        if chain_id is None and contract_row is None:
            # can't infer; require chain_id for deterministic uniqueness domain
            return _finish_err(_err("VALIDATION_ERROR", "chain_id is required when it cannot be inferred from stored data."))

    # Create pending transaction with unique tx_hash per chain_id
    txs = _load("transactions.json")
    if not isinstance(txs, list):
        txs = []

    existing_hashes = set()
    for tx in txs:
        if isinstance(tx, dict) and tx.get("chain_id") == chain_id and isinstance(tx.get("tx_hash"), str):
            existing_hashes.add(tx["tx_hash"].lower())

    # Generate unique-looking tx_hash
    # deterministic-ish entropy; loop to avoid collision in store
    tx_hash = None
    for _ in range(50):
        raw = secrets.token_bytes(32)
        h = "0x" + hashlib.sha256(raw).hexdigest()
        if h.lower() not in existing_hashes:
            tx_hash = h
            break
    if tx_hash is None:
        return _finish_err(_err("CONFLICT", "Unable to generate a unique tx_hash; please retry."))

    # ID generation
    def _next_id(prefix, rows):
        m = 0
        for r in rows:
            if isinstance(r, dict) and isinstance(r.get("id"), str) and r["id"].startswith(prefix):
                tail = r["id"][len(prefix):]
                if tail.isdigit():
                    m = max(m, int(tail))
        return f"{prefix}{m+1:06d}"

    tx_id = _next_id("coti_tx_", txs)

    new_tx = {
        "id": tx_id,
        "chain_id": chain_id,
        "tx_hash": tx_hash,
        "initiator_account_id": acct["id"],
        "tool_name": "transfer_private_erc721",
        "tx_type": "private_erc721_transfer",
        "to_address": contract_address,  # contract interaction target
        "contract_id": contract_row.get("id") if isinstance(contract_row, dict) else None,
        "value_wei": None,
        "function_selector": None,
        "call_data_hex": None,
        "inputs_json": {
            "contract_address": contract_address,
            "to_address": to_address,
            "token_id": token_id
        },
        "submitted_at": now,
        "mined_at": None,
        "block_number": None,
        "status": "pending",
        "failure_reason": None,
        "created_at": now,
        "updated_at": now
    }

    # Enforce tx_hash uniqueness constraint (chain_id, lower(tx_hash))
    for tx in txs:
        if isinstance(tx, dict) and tx.get("chain_id") == chain_id and (tx.get("tx_hash") or "").lower() == tx_hash.lower():
            return _finish_err(_err("CONFLICT", "Transaction hash already exists for chain_id.", chain_id=chain_id, tx_hash=tx_hash))

    txs.append(new_tx)
    _save("transactions.json", txs)

    return _finish_ok({
        "transaction": new_tx,
        "tx_hash": tx_hash
    })

