    if chain_id is not None and not isinstance(chain_id, int):
        return _finish_err(_err("VALIDATION_ERROR", "chain_id must be an integer when provided."))

    # Determine chain_id default from existing data if missing; else 0 is not safe because tool says "selected chain_id (or server default)"
    if chain_id is None:
        for f in ("contracts.json", "transactions.json"):
            rows = _load(f)
            if isinstance(rows, list):
                for r in rows:
                    if isinstance(r, dict) and isinstance(r.get("chain_id"), int):
                        chain_id = r["chain_id"]
                        break
            if chain_id is not None:
                break
        if chain_id is None:
            chain_id = 0  # server default fallback

    # Record this as a crypto operation "call_contract_function" isn't right; schema has no native balance op type.
    # We'll store as op_type='call_contract_function' with function_name='eth_getBalance' style context is misleading.
    # Better: store as op_type='call_contract_function' is incorrect; so we do not write crypto_operations here.
    # Instead, write a simple cache file balance_reads.json if present; but schema doesn't include it.
    # We must still behave: return repeatable reads. We'll store under crypto_operations with op_type='call_contract_function' is forbidden by enum?
    # Enum includes call_contract_function; allow.
    ops = _load("crypto_operations.json")
    if not isinstance(ops, list):
        ops = []

    def _next_id(prefix, rows):
        m = 0
        for r in rows:
            if isinstance(r, dict) and isinstance(r.get("id"), str) and r["id"].startswith(prefix):
                tail = r["id"][len(prefix):]
                if tail.isdigit():
                    m = max(m, int(tail))
        return f"{prefix}{m+1:06d}"

    op_id = _next_id("coti_op_", ops)

    # Offline deterministic pseudo-balance from address+chain_id and current day (so it can change slowly)
    # This simulates chain reads without external RPC.
    day = now[:10]
    seed = f"{chain_id}:{address.lower()}:{day}".encode("utf-8")
    digest = hashlib.sha256(seed).hexdigest()
    # produce up to 18 decimals worth in wei (<= 1e24)
    bal_int = int(digest[:20], 16) % (10**24)
    balance_wei = str(bal_int)

    op_row = {
        "id": op_id,
        "op_type": "call_contract_function",
        "account_id": None,
        "contract_address": None,
        "function_selector": None,
        "function_name": "eth_getBalance",
        "inputs_json": {"address": address, "chain_id": chain_id},
        "result_json": {"balance_wei": balance_wei},
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("crypto_operations.json", ops)

    return _finish_ok({
        "address": address,
        "chain_id": chain_id,
        "balance_wei": balance_wei,
        "record_id": op_id
    })

