    # Resolve optional account context (only validate if provided)
    acct = None
    if account_id is not None:
        if not isinstance(account_id, str) or not re.fullmatch(r"^coti_acct_[0-9A-Z]{18,}$", account_id):
            return _finish_err(_err("VALIDATION_ERROR", "account_id must match ^coti_acct_[0-9A-Z]{18,}$."))
        accounts = _load("accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acct = a
                break
        if acct is None:
            return _finish_err(_err("NOT_FOUND", "account_id not found.", account_id=account_id))
        if acct.get("status") != "active":
            return _finish_err(_err("INVALID_TRANSITION", "account is not active.", account_id=account_id, status=acct.get("status")))

    # Determine chain_id default from stored contract if possible; else from any row; else 0
    if chain_id is None:
        contracts = _load("contracts.json")
        if isinstance(contracts, list):
            for c in contracts:
                if isinstance(c, dict) and (c.get("address") or "").lower() == contract_address.lower() and isinstance(c.get("chain_id"), int):
                    chain_id = c["chain_id"]
                    break
        if chain_id is None:
            txs = _load("transactions.json")
            if isinstance(txs, list):
                for tx in txs:
                    if isinstance(tx, dict) and isinstance(tx.get("chain_id"), int):
                        chain_id = tx["chain_id"]
                        break
        if chain_id is None:
            chain_id = 0

    # Record crypto operation
    ops = _load("crypto_operations.json")
    if not isinstance(ops, list):
        ops = []

    def _next_id(prefix, rows):
        m = 0
        for r in rows:
            if isinstance(r, dict) and isinstance(r.get("id"), str) and r["id"].startswith(prefix):
                tail = r["id"][len(prefix):]
                if tail.isdigit():
                    m = max(m, int(tail))
        return f"{prefix}{m+1:06d}"

    op_id = _next_id("coti_op_", ops)

    # Offline deterministic "eth_call" simulation: hash of (chain_id, contract, function, inputs)
    payload = {
        "chain_id": chain_id,
        "contract_address": contract_address,
        "function_name": function_name.strip(),
        "inputs": inputs or {},
    }
    blob = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    digest = hashlib.sha256(blob).hexdigest()

    # Produce a stable pseudo-result; when ABI is provided, return a more structured output
    if abi_json is None:
        result = {"raw_result_hex": "0x" + digest}
    else:
        # Try to detect an output type in ABI; if not possible, return generic decoded-like structure
        # (No full ABI encoding/decoding offline.)
        result = {
            "decoded": True,
            "result": {
                "type": "bytes32",
                "value": "0x" + digest[:64]
            }
        }

    op_row = {
        "id": op_id,
        "op_type": "call_contract_function",
        "account_id": acct.get("id") if isinstance(acct, dict) else None,
        "contract_address": contract_address,
        "function_selector": None,
        "function_name": function_name.strip(),
        "inputs_json": {
            "chain_id": chain_id,
            "inputs": inputs or {},
            "abi_provided": abi_json is not None
        },
        "result_json": result,
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("crypto_operations.json", ops)

    return _finish_ok({
        "chain_id": chain_id,
        "contract_address": contract_address,
        "function_name": function_name.strip(),
        "inputs": inputs or {},
        "result": result,
        "record_id": op_id
    })

def decode_event_data(event_signature, topics, data, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "decode_event_data"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(ts):
        try:
            if isinstance(ts, str) and ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
        except Exception:
            return None

    def _limits():
        usage = _load("usage_counters.json")
        rl_window_s, rl_max, daily_max = 60, 120, 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            v = lim.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                rl_max = v
            v = lim.get("daily_quota")
            if isinstance(v, int) and v > 0:
                daily_max = v
        return rl_window_s, rl_max, daily_max

    def _enforce_or_error():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rl_window_s, rl_max, daily_max = _limits()
        within_window = 0
        within_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= rl_window_s:
                within_window += 1
            if ts.date() == now_dt.date():
                within_day += 1
        if within_window >= rl_max:
            return _err("RATE_LIMIT", f"Rate limit exceeded: max {rl_max} requests per {rl_window_s} seconds.", limit=rl_max, window_seconds=rl_window_s)
        if within_day >= daily_max:
            return _err("QUOTA_EXCEEDED", f"Daily quota exceeded: max {daily_max} requests per day.", limit=daily_max)
        return None

    def _append_request_log(status, error_code=None, crypto_operation_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "crypto_operation_id": crypto_operation_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "created_at": now,
        })
        _save("request_logs.json", logs)

    lim_err = _enforce_or_error()
    if lim_err:
        _append_request_log("error", lim_err["error"]["code"], None)
        return lim_err

    # Validate - relax: vendor parameter schema allows "event_signature" (human readable) and does not require topic0 match.
    if not isinstance(event_signature, str) or not event_signature.strip():
        op_id = "coti_op_" + secrets.token_hex(12)
        ops = _load("crypto_operations.json")
        if not isinstance(ops, list):
            ops = []
        ops.append({
            "id": op_id,
            "op_type": "decode_event_data",
            "account_id": None,
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"event_signature": event_signature, "topics": topics, "data": data},
            "result_json": None,
            "status": "failed",
            "error_message": "event_signature must be a non-empty string.",
            "created_at": now,
            "updated_at": now,
        })
        _save("crypto_operations.json", ops)
        _append_request_log("error", "VALIDATION_ERROR", op_id)
        return _err("VALIDATION_ERROR", "event_signature must be a non-empty string.", crypto_operation_id=op_id)

    if not isinstance(topics, list) or len(topics) < 1:
        op_id = "coti_op_" + secrets.token_hex(12)
        ops = _load("crypto_operations.json")
        if not isinstance(ops, list):
            ops = []
        ops.append({
            "id": op_id,
            "op_type": "decode_event_data",
            "account_id": None,
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"event_signature": event_signature, "topics": topics, "data": data},
            "result_json": None,
            "status": "failed",
            "error_message": "topics must be a non-empty array.",
            "created_at": now,
            "updated_at": now,
        })
        _save("crypto_operations.json", ops)
        _append_request_log("error", "VALIDATION_ERROR", op_id)
        return _err("VALIDATION_ERROR", "topics must be a non-empty array.", crypto_operation_id=op_id)

    hex_re = re.compile(r"^0x[0-9a-fA-F]*$")
    topic_re = re.compile(r"^0x[0-9a-fA-F]{0,64}$")
    for i, t in enumerate(topics):
        if not isinstance(t, str) or not t.startswith("0x") or not topic_re.match(t):
            op_id = "coti_op_" + secrets.token_hex(12)
            ops = _load("crypto_operations.json")
            if not isinstance(ops, list):
                ops = []
            ops.append({
                "id": op_id,
                "op_type": "decode_event_data",
                "account_id": None,
                "contract_address": None,
                "function_selector": None,
                "function_name": None,
                "inputs_json": {"event_signature": event_signature, "topics": topics, "data": data},
                "result_json": None,
                "status": "failed",
                "error_message": f"topics[{i}] must be a 0x-prefixed hex string up to 32 bytes (0..64 hex chars).",
                "created_at": now,
                "updated_at": now,
            })
            _save("crypto_operations.json", ops)
            _append_request_log("error", "VALIDATION_ERROR", op_id)
            return _err("VALIDATION_ERROR", f"topics[{i}] must be a 0x-prefixed hex string up to 32 bytes (0..64 hex chars).", index=i, crypto_operation_id=op_id)

    if not isinstance(data, str) or not hex_re.match(data) or (len(data) % 2 != 0):
        op_id = "coti_op_" + secrets.token_hex(12)
        ops = _load("crypto_operations.json")
        if not isinstance(ops, list):
            ops = []
        ops.append({
            "id": op_id,
            "op_type": "decode_event_data",
            "account_id": None,
            "contract_address": None,
            "function_selector": None,
            "function_name": None,
            "inputs_json": {"event_signature": event_signature, "topics": topics, "data": data},
            "result_json": None,
            "status": "failed",
            "error_message": "data must be a 0x-prefixed hex string with even length.",
            "created_at": now,
            "updated_at": now,
        })
        _save("crypto_operations.json", ops)
        _append_request_log("error", "VALIDATION_ERROR", op_id)
        return _err("VALIDATION_ERROR", "data must be a 0x-prefixed hex string with even length.", crypto_operation_id=op_id)

    # Minimal decoder: derive event_name if signature looks like Name(type,...) else None.
    ev_name = None
    m = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)\s*$", event_signature)
    param_types = []
    if m:
        ev_name = m.group(1)
        inner = m.group(2).strip()
        if inner == "":
            param_types = []
        else:
            param_types = [p.strip() for p in inner.split(",")]

    # Try to decode non-indexed args from data in 32-byte slots. This is best-effort and will not fail on size mismatch.
    decoded = []
    data_hex = data[2:]
    if len(data_hex) % 64 != 0:
        # best-effort: keep raw, but mark decode_failed
        op_status = "failed"
        err_msg = "data length is not a multiple of 32 bytes; cannot ABI-decode."
        result = None
    else:
        words = [data_hex[i:i+64] for i in range(0, len(data_hex), 64)]
        # If signature provides types, use them (only a few basic ones).
        def _decode_word(t, w):
            t = (t or "").strip()
            if t in ("uint", "uint256", "uint112", "uint128", "uint64", "uint32", "uint16", "uint8"):
                return int(w, 16)
            if t == "address":
                return "0x" + w[-40:]
            if t == "bool":
                return int(w, 16) != 0
            # fallback: return hex
            return "0x" + w

        if param_types:
            for idx, t in enumerate(param_types):
                if idx < len(words):
                    decoded.append({"index": idx, "type": t, "value": _decode_word(t, words[idx])})
                else:
                    decoded.append({"index": idx, "type": t, "value": None})
        else:
            for idx, w in enumerate(words):
                decoded.append({"index": idx, "type": None, "value": "0x" + w})

        op_status = "succeeded"
        err_msg = None
        result = {"event_signature": event_signature, "event_name": ev_name, "decoded_args": decoded}

    op_id = "coti_op_" + secrets.token_hex(12)
    ops = _load("crypto_operations.json")
    if not isinstance(ops, list):
        ops = []
    ops.append({
        "id": op_id,
        "op_type": "decode_event_data",
        "account_id": None,
        "contract_address": None,
        "function_selector": None,
        "function_name": ev_name,
        "inputs_json": {"event_signature": event_signature, "topics": topics, "data": data},
        "result_json": result,
        "status": op_status,
        "error_message": err_msg,
        "created_at": now,
        "updated_at": now,
    })
    _save("crypto_operations.json", ops)

    if op_status != "succeeded":
        _append_request_log("error", "VALIDATION_ERROR", op_id)
        return _err("VALIDATION_ERROR", err_msg, crypto_operation_id=op_id)

    _append_request_log("success", None, op_id)
    return {"crypto_operation": ops[-1]}

def get_transaction_logs(tx_hash, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_id = "req_" + hashlib.sha256((str(time.time()) + "|get_transaction_logs").encode("utf-8")).hexdigest()[:16]
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_call(status, error_code=None):
        crypto_ops = _load("crypto_operations.json")
        op_id = "coti_op_" + hashlib.sha256((req_id + "|call").encode("utf-8")).hexdigest()[:24]
        latency_ms = int((time.time() - t0) * 1000)
        crypto_ops.append({
            "id": op_id,
            "op_type": "call_contract_function",
            "account_id": None,
            "contract_address": None,
            "function_selector": None,
            "function_name": "get_transaction_logs",
            "inputs_json": {"tx_hash": tx_hash, "limit": limit, "cursor": cursor, "request_id": req_id, "latency_ms": latency_ms},
            "result_json": {"status": status, "error_code": error_code} if status != "succeeded" else {"status": status},
            "status": "succeeded" if status == "succeeded" else "failed",
            "error_message": None if status == "succeeded" else (error_code or "failed"),
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)

    if not isinstance(tx_hash, str) or re.fullmatch(r"^0x[0-9a-fA-F]{64}$", tx_hash) is None:
        _record_call("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tx_hash must be a valid 0x-prefixed 32-byte hash")
    if limit is not None:
        if not isinstance(limit, int):
            _record_call("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        if limit < 1:
            _record_call("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be >= 1")

    txs = _load("transactions.json")
    logs = _load("transaction_logs.json")

    # Resolve transaction by tx_hash (unique per chain_id, but caller didn't supply chain_id here)
    tx = None
    for r in txs:
        if isinstance(r, dict) and (r.get("tx_hash") or "").lower() == tx_hash.lower():
            tx = r
            break
    if not tx:
        _record_call("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "Transaction not found")

    tx_id = tx.get("id")
    tx_logs = [lr for lr in logs if lr.get("transaction_id") == tx_id]
    tx_logs.sort(key=lambda x: (x.get("log_index") if isinstance(x.get("log_index"), int) else 10**18, x.get("id") or ""))

    # Cursor is base64url of start_index integer
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _record_call("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("i:"):
                _record_call("failed", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start = int(raw[2:])
            if start < 0:
                raise ValueError("neg")
        except Exception:
            _record_call("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    lim = limit if limit is not None else 100
    page = tx_logs[start:start + lim]
    next_cursor = None
    has_more = (start + lim) < len(tx_logs)
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"i:{start+lim}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Return envelope
    _record_call("succeeded")
    return {
        "transaction": {
            "id": tx.get("id"),
            "chain_id": tx.get("chain_id"),
            "tx_hash": tx.get("tx_hash"),
            "status": tx.get("status"),
            "submitted_at": tx.get("submitted_at"),
            "mined_at": tx.get("mined_at"),
            "block_number": tx.get("block_number")
        },
        "logs": page,
        "meta": {
            "request_id": req_id,
            "timestamp": now,
            "total": len(tx_logs),
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_account(account_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_id = "req_" + hashlib.sha256((str(time.time()) + "|get_account").encode("utf-8")).hexdigest()[:16]
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record(status, error_code=None):
        crypto_ops = _load("crypto_operations.json")
        op_id = "coti_op_" + hashlib.sha256((req_id + "|call").encode("utf-8")).hexdigest()[:24]
        latency_ms = int((time.time() - t0) * 1000)
        crypto_ops.append({
            "id": op_id,
            "op_type": "call_contract_function",
            "account_id": None,
            "contract_address": None,
            "function_selector": None,
            "function_name": "get_account",
            "inputs_json": {"account_id": account_id, "request_id": req_id, "latency_ms": latency_ms},
            "result_json": {"status": status, "error_code": error_code} if status != "succeeded" else {"status": status},
            "status": "succeeded" if status == "succeeded" else "failed",
            "error_message": None if status == "succeeded" else (error_code or "failed"),
            "created_at": now,
            "updated_at": now
        })
        _save("crypto_operations.json", crypto_ops)

    if not isinstance(account_id, str) or re.fullmatch(r"^coti_acct_[A-Za-z0-9]+$", account_id) is None:
        _record("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")

    accts = _load("accounts.json")
    acct = None
    for r in accts:
        if isinstance(r, dict) and r.get("id") == account_id:
            acct = r
            break

    if not acct:
        _record("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "No account exists with that id")

    def _mask(s):
        if not isinstance(s, str) or s == "":
            return None
        if len(s) <= 10:
            return "***"
        return s[:6] + "…" + s[-4:]

    # Redact key material: never return encrypted payloads in full (treat as sensitive).
    out = dict(acct)
    out["private_key_encrypted"] = _mask(acct.get("private_key_encrypted"))
    out["aes_key_encrypted"] = _mask(acct.get("aes_key_encrypted"))

    _record("succeeded")
    return {"account": out, "meta": {"request_id": req_id, "timestamp": now}}

def archive_account(account_id, reason=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "archive_account"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": f"coti_req_{secrets.token_urlsafe(10)}",
            "endpoint": endpoint,
