            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^coti_acct_[A-Za-z0-9]+$", account_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
    if reason is not None:
        if not isinstance(reason, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
