            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reason exceeds maxLength 512.", field="reason")

    accounts = _load("accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
