            break
    if acct is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No account exists with that id.", account_id=account_id)

    if acct.get("status") == "archived":
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Account is already archived.", account_id=account_id)

    # Lifecycle transition enforcement: active -> archived only
    if acct.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Account status does not allow archiving.", from_status=acct.get("status"), to_status="archived")

    # Enforce rule: exactly one active default must exist.
    # If archiving the only active account OR the only active default with no other active accounts to become default => conflict.
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if len(active_accounts) <= 1:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Cannot archive the only active account; exactly one active default must remain.", account_id=account_id)

    is_default = bool(acct.get("is_default"))
    if is_default:
        # Need at least one other active account to become default
        other_active = [a for a in active_accounts if a.get("id") != account_id]
        if not other_active:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Cannot archive the default account when no other active account exists to become default.", account_id=account_id)

        # Choose another active account deterministically (oldest created_at then id)
        def _key(a):
            ca = a.get("created_at") or ""
            return (ca, a.get("id") or "")
        other_active_sorted = sorted(other_active, key=_key)
        new_default_id = other_active_sorted[0].get("id")

        # Apply: exactly one active default true; all others false; archived account default false
        for a in accounts:
            if a.get("status") != "active":
                a["is_default"] = False
            else:
                a["is_default"] = (a.get("id") == new_default_id)

    # Archive the target
    acct["status"] = "archived"
    acct["is_default"] = False
    acct["archived_at"] = now
    acct["updated_at"] = now
    if reason is not None:
        acct["_archive_reason"] = reason  # audit metadata (not part of schema, stored as extra)

    # Post-condition: exactly one active default
    active_after = [a for a in accounts if a.get("status") == "active"]
    defaults_after = [a for a in active_after if a.get("is_default") is True]
    if len(active_after) > 0 and len(defaults_after) != 1:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Archiving would violate the default-account invariant (exactly one active default).")

    _save("accounts.json", accounts)

    # Return sanitized account (never plaintext keys)
    out = dict(acct)
    if "private_key_encrypted" in out:
        out["private_key_encrypted"] = None
        out["private_key_masked"] = "encrypted"
    if "aes_key_encrypted" in out:
        out["aes_key_encrypted"] = None
        out["aes_key_masked"] = "encrypted" if acct.get("aes_key_encrypted") else None

    _log("ok", None)
    return {"account": out}

def list_transactions(chain_id=None, status=None, initiator_account_id=None, tx_hash=None, contract_id=None, tool_name=None, tx_type=None, submitted_after=None, submitted_before=None, page_size=None, page_token=None, order_by=None, order_dir=None, **_extra):
    import json, os, datetime, re, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_transactions"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": f"coti_req_{secrets.token_urlsafe(10)}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate filters
    if chain_id is not None:
        if not isinstance(chain_id, int) or chain_id < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "chain_id must be an integer >= 1.", field="chain_id")
    if status is not None:
        if status not in ("pending", "confirmed", "failed", "dropped"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if initiator_account_id is not None:
        if not isinstance(initiator_account_id, str) or not re.match(r"^coti_acct_[A-Za-z0-9]+$", initiator_account_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "initiator_account_id is malformed.", field="initiator_account_id")
    if tx_hash is not None:
        if not isinstance(tx_hash, str) or not re.match(r"^0x[a-fA-F0-9]{64}$", tx_hash):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tx_hash is malformed.", field="tx_hash")
    if contract_id is not None:
        if not isinstance(contract_id, str) or not re.match(r"^coti_ctr_[A-Za-z0-9]+$", contract_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contract_id is malformed.", field="contract_id")
    if tool_name is not None:
        if not isinstance(tool_name, str) or not (1 <= len(tool_name) <= 128):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tool_name must be a non-empty string up to 128 chars.", field="tool_name")
    if tx_type is not None:
        if not isinstance(tx_type, str) or not (1 <= len(tx_type) <= 64):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tx_type must be a non-empty string up to 64 chars.", field="tx_type")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")
    if order_by is None:
        order_by = "submitted_at"
    if order_by not in ("submitted_at", "created_at", "updated_at"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order_by.", field="order_by")
    if order_dir is None:
        order_dir = "desc"
    if order_dir not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order_dir.", field="order_dir")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        ss = s
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        # Accept ISO8601 with timezone or naive; store as aware UTC
        dt = datetime.datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        else:
            dt = dt.astimezone(datetime.timezone.utc)
        return dt

    try:
        after_dt = _parse_dt(submitted_after, "submitted_after")
        before_dt = _parse_dt(submitted_before, "submitted_before")
    except ValueError as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid date-time format.", field=str(e))

    # Decode page_token: base64url JSON {"offset": int}
    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or len(page_token) < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string.", field="page_token")
        try:
            padded = page_token + "=" * (-len(page_token) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")

    txs = _load("transactions.json")

    def _dt_from_row(val):
        if not isinstance(val, str):
            return None
        s = val
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except ValueError:
            return None

    # Apply filters
    res = []
    tx_hash_l = tx_hash.lower() if isinstance(tx_hash, str) else None
    for r in txs:
        if chain_id is not None and r.get("chain_id") != chain_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if initiator_account_id is not None and r.get("initiator_account_id") != initiator_account_id:
            continue
        if tx_hash_l is not None and isinstance(r.get("tx_hash"), str) and r.get("tx_hash").lower() != tx_hash_l:
            continue
        if tx_hash_l is not None and not isinstance(r.get("tx_hash"), str):
            continue
        if contract_id is not None and r.get("contract_id") != contract_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if tx_type is not None and r.get("tx_type") != tx_type:
            continue

        sub_dt = _dt_from_row(r.get("submitted_at"))
        if after_dt is not None:
            if sub_dt is None or sub_dt < after_dt:
                continue
        if before_dt is not None:
            if sub_dt is None or sub_dt > before_dt:
                continue
        res.append(r)

    # Sort
    def _sort_key(r):
        dt = _dt_from_row(r.get(order_by))
        # Put invalid/missing timestamps last for asc, first for desc (match typical behavior: missing are least informative)
        if dt is None:
            sentinel = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if order_dir == "desc" else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            dt = sentinel
        return (dt, r.get("id") or "")

    reverse = (order_dir == "desc")
    res_sorted = sorted(res, key=_sort_key, reverse=reverse)

    total = len(res_sorted)
    page = res_sorted[offset:offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        tok_obj = {"offset": next_offset}
        tok_raw = json.dumps(tok_obj, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(tok_raw).decode("utf-8").rstrip("=")

    _log("ok", None)
    return {
        "transactions": page,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_transaction(transaction_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0345000" if __import__("os").path.isdir("./environment_mix/0345000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_transaction"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_ts(ts):
        try:
            if isinstance(ts, str) and ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts) if isinstance(ts, str) else None
        except Exception:
            return None

    def _limits():
        usage = _load("usage_counters.json")
        rl_window_s, rl_max, daily_max = 60, 120, 5000
        if isinstance(usage, dict):
            lim = usage.get("limits") or {}
            v = lim.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                rl_max = v
            v = lim.get("daily_quota")
            if isinstance(v, int) and v > 0:
                daily_max = v
        return rl_window_s, rl_max, daily_max

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rl_window_s, rl_max, daily_max = _limits()
        within_window = 0
        within_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= rl_window_s:
                within_window += 1
            if ts.date() == now_dt.date():
                within_day += 1
        if within_window >= rl_max:
            return _err("RATE_LIMIT", f"Rate limit exceeded: max {rl_max} requests per {rl_window_s} seconds.", limit=rl_max, window_seconds=rl_window_s)
        if within_day >= daily_max:
            return _err("QUOTA_EXCEEDED", f"Daily quota exceeded: max {daily_max} requests per day.", limit=daily_max)
        return None

    def _append_request_log(status, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rec = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "created_at": now,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if isinstance(extra, dict):
            rec.update(extra)
        logs.append(rec)
        _save("request_logs.json", logs)

        usage = _load("usage_counters.json")
        if not isinstance(usage, dict):
            usage = {}
        usage.setdefault("counters", {})
        usage["counters"]["requests_total"] = int(usage["counters"].get("requests_total", 0) or 0) + 1
        usage["counters"]["requests_" + endpoint] = int(usage["counters"].get("requests_" + endpoint, 0) or 0) + 1
        if status != "ok":
            usage["counters"]["errors_total"] = int(usage["counters"].get("errors_total", 0) or 0) + 1
        usage["updated_at"] = now
        _save("usage_counters.json", usage)

    lim_err = _enforce_limits()
    if lim_err:
        _append_request_log("err", lim_err["error"]["code"])
        return lim_err

    try:
        if not isinstance(transaction_id, str) or not re.fullmatch(r"^coti_tx_[A-Za-z0-9]+$", transaction_id):
            e = _err("VALIDATION_ERROR", "transaction_id is malformed.", field="transaction_id")
            _append_request_log("err", e["error"]["code"])
            return e

        txs = _load("transactions.json")
        if not isinstance(txs, list):
            txs = []

        tx = None
        for r in txs:
            if isinstance(r, dict) and r.get("id") == transaction_id:
                tx = r
                break

        if tx is None:
            e = _err("NOT_FOUND", "No transaction exists with that id.", transaction_id=transaction_id)
            _append_request_log("err", e["error"]["code"])
            return e

        _append_request_log("ok", extra={"transaction_id": transaction_id})
        return {"transaction": tx}
    except Exception as e:
        err = _err("VALIDATION_ERROR", "Unexpected error while processing get_transaction.", detail=str(e))
        _append_request_log("err", err["error"]["code"])
        return err
